  ["_CeladonMansion3FGameScriptPCText"] = "È il copione del\ngioco! Meglio non\11guardare il finale!",
  ["_CeladonMansion3FGraphicArtistText"] = "Sono il grafico!\11Ti ho disegnato io!",
  ["_CeladonMansion3FPlayingGamePCText"] = "Qualcuno sta\ngiocando invece\11di lavorare!",
  ["_CeladonMansion3FProgrammerText"] = "Io? Sono il\nprogrammatore!",
  ["_CeladonMansion3FWriterText"] = "Ho scritto io\nla storia! ERIKA\11è carina, eh?\12Mi piace molto\nanche MISTY!\12E mi piace\nanche SABRINA!",
  ["_CeladonMansionRoofHouseHikerText"] = "Io so tutto sul\nmondo dei POKéMON\11nel tuo GAME BOY!\12Incontra i tuoi\namici e scambia\11i POKéMON!",
  ["_CeladonMansionRoofHouseSignText"] = "SO TUTTO IO!",
  ["_CeladonMart1FCurrentFloorSignText"] = "PT: BANCO\nINFORMAZIONI",
  ["_CeladonMart1FDirectorySignText"] = "PT: BANCO\nINFORMAZIONI\121P: NEGOZIO PER\nALLENATORI\122P: VIDEOGIOCHI\123P: REGALI\124P: FARMACIA\12ULTIMO PIANO:\nDISTRIBUTORI",
  ["_CeladonMart1FReceptionistText"] = "Benvenuto al\nCENTRO COMMERCIALE\11di AZZURROPOLI.\12Il tabellone a\ndestra descrive i\11piani del negozio.",
  ["_CeladonMart2FCurrentFloorSignText"] = "Strumenti di alta\nqualità per\11allenatori.\121P: NEGOZIO PER\nALLENATORI",
  ["_CeladonMart2FGirlText"] = "Per i lunghi\nviaggi dovresti\11comprare\11REVITALIZZANTE.",
  ["_CeladonMart2FMiddleAgedManText"] = "Il SUPERREPELL.\ntiene lontani i\11POKéMON deboli...\12È un REPELLENTE\npiù potente!",
 ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "La MT18 è\nCONTATORE.\11Forza, andiamo!...\11Buona fortuna!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Lo zaino è pieno\ndi strumenti!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "Oh, ciao! Ho\nfinito! Ho\11completato\11i POKéMON!\12Tu no? Prendi.\nTi aiuterà!",
  ["_CeladonMart3FCurrentFloorSignText"] = "2P: VIDEOGIOCHI",
  ["_CeladonMart3FFightingGameText"] = "Un gioco di\nlotta! Sembra\11molto difficile!",
  ["_CeladonMart3FGameBoyKid1Text"] = "Ogni POKéMON\ncatturato ha un\11n. ID e un AO.\12L'AO è il nome\ndell'Allenatore\11Originale!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Evvai!\12Il mio amico mi\nscambierà il suo\11KANGASKHAN per\11il mio GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Un GRAVELER!\12Mi piacciono i\nGRAVELER! Li\11colleziono!\12Cosa?\12GRAVELER si è\nevoluto in un\11altro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Riconosci\ni POKéMON\11che hai scambiato\11dal loro n. ID!",
  ["_CeladonMart3FPokemonPosterText"] = "Rosso e Blu!\nDue giochi\11dei POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Un rompicapo!\nSembra molto\11appassionante!",
  ["_CeladonMart3FRPGText"] = "Un gioco di ruolo.\nForte! Ma non\11ho tempo!",
  ["_CeladonMart3FSNESText"] = "È un SUPER\nNINTENDO!",
  ["_CeladonMart3FSportsGameText"] = "Un gioco di\nsport! Piacciono\11a mio papà!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Dillo con un\nregalo!\123P: REGALI\12Evoluzione\nSpeciale!\11Pietre elementali\11in vendita!",
  ["_CeladonMart4FSuperNerdText"] = "Comprerò una\nPOKé BAMBOLA\11per la mia\11ragazza!",
  ["_CeladonMart4FYoungsterText"] = "Senti questa!\12Puoi fuggire da\nun POKéMON\11selvatico se lo\11distrai con una\11POKé BAMBOLA!",
  ["_CeladonMart5FCurrentFloorSignText"] = "4P: FARMACIA",
  ["_CeladonMart5FGentlemanText"] = "Gli integratori\nper POKéMON si\11vendono solo qui!\12Usa CALCIO per\naumentare le\11stat. SPECIALI.\12Usa CARBURANTE\nper aumentare la\11VELOCITÀ.",
  ["_CeladonMart5FSailorText"] = "Sono qui per gli\nintegratori dei\11POKéMON!\12Le PROTEINE\naumentano la\11potenza d'ATTACCO.\12Il FERRO aumenta\nla DIFESA.",
  ["_CeladonMartRoofCurrentFloorSignText"] = "ULTIMO PIANO:\nDISTRIBUTORI",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ho sete!\nVoglio qualcosa\11da bere!\12Vuoi darle\nda bere?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Cosa vuoi\ndarle da bere?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "No, grazie!\nNon ho molta\11sete!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ho sete!\nVoglio qualcosa\11da bere!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Non hai spazio\nper questo!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} riceve\nMT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\12La {RAM:wStringBuffer}\ncontiene\11GELORAGGIO!\12A volte congela\nil nemico!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\12La {RAM:wStringBuffer}\ncontiene FRANA!\12A volte fa\ntentennare il\11nemico...",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\12La MT49 contiene\nTRIPLETTA!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Evviva!\12ACQUA FRESCA!\12Grazie!\12Tieni, è per\nte!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Evviva!\12LIMONATA!\12Grazie!\12Tieni, è per\nte!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Evviva!\12GASSOSA!\12Grazie!\12Tieni, è per\nte!",
  ["_CeladonMartRoofSuperNerdText"] = "Mia sorella fa\nl'allenatrice,\11davvero!\12Ma è così\ninfantile che\11mi fa impazzire!",
  ["_CeladonPokecenterBeautyText"] = "Ho pedalato in\nsalita lungo la\11Pista Ciclabile\11da FUCSIAPOLI!",
  ["_CeladonPokecenterGentlemanText"] = "Il POKé FLAUTO\nsveglia i POKéMON\11con un suono che\11solo loro sentono!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTACCO di tutti\ni POKéMON\11aumenta un po'.\12E puoi usare\nFLASH quando\11vuoi.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "I POKéMON fino\nal livello 30 ti\11obbediranno.\12Quelli di livello\nsuperiore saranno\11incontrollabili!\12E potrai usare\nTAGLIO fuori\11dalla lotta.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tutti i POKéMON\nti obbediranno!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "I POKéMON fino\nal livello 70 ti\11obbediranno.\12Quelli di livello\nsuperiore saranno\11incontrollabili!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Solo gli allenatori\npiù abili hanno\11le MEDAGLIE.\12Vedo che ne hai\nalmeno una.\12Queste MEDAGLIE\nnascondono segreti\11incredibili!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Vieni a trovarmi\nquando vuoi.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dimmi...\12Quale delle 8\nMEDAGLIE devo\11descriverti?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "I POKéMON fino\nal livello 50 ti\11obbediranno.\12Quelli di livello\nsuperiore saranno\11incontrollabili!\12E potrai usare\nFORZA fuori\11dalla lotta.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DIFESA di\ntutti i POKéMON\11aumenta un po'.\12E potrai usare\nSURF fuori\11dalla lotta.",
 ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCITÀ di\ntutti i POKéMON\11aumenta un po'.\12E potrai usare\nVOLAR fuori\11dalla lotta.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le abilità\nSPECIALI dei tuoi\11POKéMON\11aumentano un po'.",
  ["_CeruleanCityBikeShopSign"] = "Erbe e grotte\nsotto controllo!\11NEGOZIO DI BICI",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "SLOWBRO, dai un\npugno! No!\11Hai fallito di\11nuovo!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "FORZA, SLOWBRO!\nUsa SONICBOOM!\11Sveglia, SLOWBRO,\11presta attenzione!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, RIPOSA!\nNo, che male!\12È così difficile\ncontrollare i\11POKéMON!\12L'obbedienza dei\nPOKéMON dipende\11dalle tue abilità\11di allenatore!",
  ["_CeruleanCityCooltrainerF2Text"] = "Voglio una bella\nBICICLETTA rossa.\12La terrò in casa\nin modo che non\11si sporchi!",
  ["_CeruleanCityCooltrainerMText"] = "Sei anche tu un\nallenatore?\11Catturare e lottare,\nche vita dura!",
  ["_CeruleanCityGuardText"] = "Queste persone\nsono state derubate.\12Sicuramente il\nTEAM ROCKET c'entra\11con questo atroce\11crimine!\12Perfino la nostra\nPOLIZIA ha problemi\11con i ROCKET!",
  ["_CeruleanCityGymSign"] = "CAPOPALESTRA di\nCELESTE:\11MISTY\12La sirena\ndistorsionata!",
  ["_CeruleanCityRivalDefeatedText"] = "Ehi!\nCalmati!\11Hai già vinto!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Sai\ncosa mi è successo?\12Sono stato da BILL\ne mi ha fatto\11vedere i suoi\11rari POKéMON!\12Questo ha aggiunto\nmolte pagine al\11mio POKéDEX!\12Non per niente BILL\nè famoso come\11POKéMANIACO!\12Ha inventato lui il\nSistema Memoria\11PC dei POKéMON!\12Dato che usi il\nsuo sistema, dovresti\11ringraziarlo!\12Beh, è meglio\nche vada!\11Arrivederci!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Ciao\n{PLAYER}!\12Te la sbrighi\nancora lentamente?\12Qui va tutto\nalla grande! Ho\11preso un mucchio\11di forti POKéMON!\12Forza {PLAYER},\nvediamo cosa hai\11catturato tu!",
  ["_CeruleanCityRivalVictoryText"] = "Heh!\nSono troppo\11in gamba per te!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\nÈ meglio che me\nne vada! Addio!",
  ["_CeruleanCityRocketIGiveUpText"] = "Alt!\nMi arrendo!\11Me ne vado\11tranquillamente!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Restituirò\nla MT che ho rubato!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} recupera\nla MT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Fai spazio per\nquesto!\12Non posso andarmene\nfinché non la prendi!",
  ["_CeruleanCityRocketText"] = "Ehi! Fuori di\nqui! Non ti\11riguarda!\12Chi, io?\nSono un semplice\11passante!",
  ["_CeruleanCitySignText"] = "CELESTE\nUna misteriosa\11aura blu la\11circonda.",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ignora\nle ordini...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO sta\ncazzeggiando...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO si è\nappisolato...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO si\nè voltato...",
  ["_CeruleanCitySuperNerd1Text"] = "Quel cespuglio\ndavanti al negozio\11mi blocca la\11strada.\12Dovrei poterlo\neludere.",
  ["_CeruleanCitySuperNerd2Text"] = "Stai compilando\nun'enciclopedia\11di POKéMON?\11Incredibile!",
  ["_CeruleanCitySuperNerd3Text"] = "Questa è la GROTTA\nIGNOTA! Vivono\11lì POKéMON\11super forti!\12Può entrare solo\nil campione della\11LEGA POKéMON!",
  ["_CeruleanCityTrainerTipsText"] = "CONSIGLI UTILI\12Premi il tasto B\ndurante l'evolu-\nzione per cancel-\nlare il processo.",
  ["_CeruleanGymAfterBattleText1"] = "Devi lottare con\naltri allenatori\11per capire quanto\11vali.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY continuerà\na migliorare!\12E non perderà con\nuno come te!",
  ["_CeruleanGymBattleText1"] = "Sono troppo\nbrava per te!\12MISTY può\naspettare!",
  ["_CeruleanGymBattleText2"] = "Splash!\nSono la prima!\12All'attacco!",
  ["_CeruleanGymEndBattleText1"] = "\nMi hai distrutta!",
  ["_CeruleanGymEndBattleText2"] = "Non\npuò essere!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Hai battuto MISTY!\nChe dire?\12Tu ed io formiamo\nun team fortissimo!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Ehi, futuro\ncampione!\12Un consiglio:\nla CAPOPALESTRA\11MISTY è esperta\11di POKéMON ACQUA!\12Puoi assorbire\nla loro acqua con\11i POKéMON d'ERBA!\12Oppure fulminarli\ncon l'elettricità!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "La MEDAGLIA\nCASCATA costringerà\11tutti i POKéMON\11sotto il livello\1130 a obbedirti!\12Inclusi i\nforestieri!\12Potrai usare\nTAGLIO quando\11vuoi!\12Puoi TAGLIARE i\npiccoli arbusti per\11aprire nuove vie!\12E ti darò la\nmia MT preferita!",
  ["_CeruleanGymMistyPreBattleText"] = "Ciao! Sei nuovo\nda queste parti!\12I veri allenatori\ndevono avere una\11strategia per\11i loro POKéMON!\12Qual è la tua\ntattica per\11catturarli?\12La mia è un'offensiva\ntotale con i POKéMON\11d'acqua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Uau!\nCi sai fare!\12Prendi la MEDAGLIA\nCASCATA per far\11sapere a tutti\11che mi hai battuto!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} ottiene\nla MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La MT11 insegna\nBOLLARAGGIO!\12Usala sui POKéMON\nd'acqua!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Meglio se gli\nfai un po' di spazio!",
  ["_CeruleanMartCooltrainerFText"] = "Hai mai visto un\nCARAMELLORARO?\12Dicono che faccia\nsalire di livello\11un POKéMON\11all'istante!",
  ["_CeruleanMartCooltrainerMText"] = "Usa REPELLENTE\nper evitare insetti\11e POKéMON deboli.\12Metti il tuo POKéMON\npiù forte in cima\11alla lista per\11risultati migliori!",
  ["_CeruleanPokecenterGentlemanText"] = "Hai sentito\nparlare di BILL?\12Dicono che sia un\nPOKéMANÍACO!\12Ma credo che la\ngente sia solo\11invidiosa.\12Chi non vorrebbe\nvantarsi dei propri\11POKéMON?",
  ["_CeruleanPokecenterGuyText"] = "BILL ha un sacco\ndi POKéMON!\12E alcuni sono\nmolto rari!",
  ["_CeruleanPokecenterSuperNerdText"] = "Quel BILL!\12Dicono che farebbe\ndi tutto per\11avere POKéMON rari!",
  ["_CeruleanTradeHouseGrannyText"] = "A mio marito\npiace scambiare\11i POKéMON.\12Se sei un\ncollezionista,\11perché non fai\11scambi con lui?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Maledetti ROCKET!\12Guarda cosa\nhanno combinato!\12Hanno rubato una\nMT per insegnare\11a EXCAVAR!\12E questo mi ha\ncreato un sacco\di problemi!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Quel che è perso,\nè perso!\12Così ho deciso di\ninsegnare a DIGLETT\11a EXCAVAR senza\11usare la MT!",
  ["_CeruleanTrashedHouseGirlText"] = "Il TEAM ROCKET\nstarebbe scavando\11per la sua via\11del male!",
  ["_CeruleanTrashedHouseWallHoleText"] = "Il TEAM ROCKET\nha aperto una\11nuova via!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: {PLAYER}!\nTutta la gloria\11è merito tuo!\12Il legame che\ncondividi coi tuoi\11POKéMON è\11meraviglioso!\12{PLAYER}!\nVieni con me!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: Hai vinto!\nCongratulazioni!\12Sei il nuovo\ncampione della\11LEGA POKéMON!\12Sei cresciuto\ntanto da quando\11sei partito con\11{RAM:wNameBuffer}!\12{PLAYER}, sei\nproprio maturato!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: {RIVAL}!\nSono molto deluso!\12Sono venuto non\nappena ho saputo\11che avevi battuto\11i SUPERQUATTRO!\12Ma quando sono\narrivato qui,\11eri già stato\11sconfitto!\12{RIVAL}!\nCapisci perché\11hai perso?\12Hai dimenticato\ndi trattare i tuoi\11POKéMON con amore\11e fiducia!\12Senza di loro,\nnon sarai mai un\11vero campione!",
  ["_ChampionsRoomOakText"] = "OAK: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Cosa? Com'è\npossibile?\12Ho allenato i miei\nPOKéMON alla\11perfezione.\12Maledizione!\nSei tu il nuovo\11campione della\11LEGA POKéMON!\12Anche se non mi\nva di ammetterlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Ciao!\nNon vedevo l'ora\11di vederti,\11{PLAYER}!\12Un rivale deve\nessere forte per\11mantenermi in\11forma!\12Usando il POKéDEX\nho cercato i\11POKéMON più forti!\12E ho creato team\nin grado di battere\11qualsiasi tipo di\11POKéMON!\12E ora...\12Il campione della\nLEGA POKéMON\11sono io!\12{PLAYER}!\nSai cosa vuol\11dire?\12Te lo dico io!\nIl miglior\11allenatore del\11mondo sono io!",
  ["_ChanseyDexEntry"] = "Un POKéMON raro\ne sfuggente che,\nsecondo la leggenda,\12porta la felicità\na chi riesce a\ncatturarlo.",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Sputa fuoco così\ncaldo da fondere\nla roccia.\12A volte causa\nincendi boschivi\nsenza volerlo.",
  ["_CharmanderDexEntry"] = "Preferisce i\nluoghi caldi.\nQuando piove,\12sembra che fuoriesca\nvapore dalla\npunta della coda.",
  ["_CharmeleonDexEntry"] = "Quando agita\nla coda infuocata,\nalza la tempera-\12tura a livelli\nmolto elevati.",
  ["_ChooseABoxText"] = "Scegli un BOX\ndi POKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "Il FUOCO è il\nmassimo per la\11tecnica delle\11scottature!\12Non sprecarlo\ncontro i POKéMON\11d'acqua!",
  ["_CinnabarGymBlainePreBattleText"] = "Heh!\nSono BLAINE!\12Il CAPOPALESTRA\ndi ISOLA CANNELLA!\12I miei feroci\nPOKéMON\11incendieranno\11chi mi sfida!\12Heh! Meglio che\ntu abbia con te\11un ANTISCOTTATURA!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Mi hai\ndistrutto!\12Hai vinto la\nMEDAGLIA VULCANO!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\nLa MT38 include\nFUOCOBOMBA!\12Insegna questo\natacco ai POKéMON\11di tipo FUOCO!\12CHARMELEON o\nPONYTA sarebbero\11un'ottima scelta!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Fai spazio per\nil mio regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Heh!\nLa MEDAGLIA\11VULCANO migliora\11le abilità\11SPECIALI dei tuoi\11POKéMON!\12Tieni, prendi\nanche questo!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}, hai\nbattuto quella\11torcia umana!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Ehi, futuro\ncampione!\12BLAINE è un\nesperto di POKéMON\11di tipo FUOCO!\12Spegni il suo\nentusiasmo con\11l'acqua!\12Porta con te\nANTISCOTTATURE!",
  ["_CinnabarGymQuizCorrectText"] = "Risposta\nesatta!\12Avanti!",
  ["_CinnabarGymQuizIncorrectText"] = "Sbagliato! Mi\nspiace!",
  ["_CinnabarGymQuizIntroText"] = "Quiz POKéMON!\12Rispondi bene e\naprirai la porta\11per la stanza\11seguente!\12Sbaglia e\nlotterai contro\11un allenatore!\12Se vuoi conser-\nvare le forze per\11il CAPOPALESTRA...\12Rispondi bene!\nVia!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Fuoco, o per\nessere precisi,\11combustione...\12Bla, bla, bla,\nbla!...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Sai quanto\npuò scaldare\11il soffito di\11fuoco di un\11POKéMON?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Ahi!\nBrucia, brucia!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Non riesco a\nfare a meno di\11rubare i POKéMON\11altrui!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ero un ladro, ma\nsono diventato\11onesto quando\11sono diventato\11allenatore!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "\nMi arrendo!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Le mie teorie\nsono troppo\11complicate per te!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Non puoi vincere!\nSono un esperto\11di POKéMON!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Ahi!\nI miei studi!",
