  ["_FuchsiaGymKogaTM06NoRoomText"] = "Fai spazio per\nquesto, ragazzo!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Unirai forza\ne intelligenza?\12Bella tattica!",
  ["_FuchsiaGymRocker1BattleText"] = "La forza non è\ntutto!\12Conta la strategia.\12Ti mostrerò come\nla strategia vince\11sulla forza!",
  ["_FuchsiaGymRocker1EndBattleText"] = "\nStraordinario!",
