  ["_FuchsiaGymRocker2BattleText"] = "Volevo fare il\nninja ed è per\11questo che sono\11venuto qui!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Uffa!\nHo perso!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Mi piacciono le\nmosse sonnifere e\11velenose perché\11durano anche\11dopo la lotta!",
  ["_FuchsiaGymRocker3BattleText"] = "Vediamo se superi\nle mie tecniche\11speciali!",
  ["_FuchsiaGymRocker3EndBattleText"] = "\nMi hai fregato!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Impressionante!\nEcco un indizio:\12guarda attentamente\nnei varchi dei\11muri invisibili!",
  ["_FuchsiaGymRocker4BattleText"] = "Alt!\nI nostri muri\11invisibili ti\11hanno bloccato?",
