  ["_FuchsiaGymRocker5AfterBattleText"] = "Ho ancora molto\nda imparare!",
  ["_FuchsiaGymRocker5BattleText"] = "Studio le tecniche\nninja con KOGA!\12I ninja usano\ngli animali da\11molto tempo!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Auuuu!",
