  ["_LavenderPokecenterLittleGirlText"] = "Ho visto la madre\ndi CUBONE morire\11cercando di fuggire\11dal TEAM ROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Questo paese è\nnoto come il\11cimitero dei POKéMON.\12I funerali si\ntengono alla\11TORRE POKéMON.",
