  ["_NothingToDepositText"] = "Non hai nulla\nda depositare.",
  ["_OHKOText"] = "KO in un colpo!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "C'è un messaggio\ne-mail!\12...\12Avviso a tutti\ngli allenatori\11di POKéMON!\12I lottatori d'élite\ndella LEGA POKéMON\11sono pronti a\11sfidarvi tutti!\12Portate i vostri\nmigliori POKéMON e\11scoprite il vostro\11punteggio!\12Sede LEGA POKéMON\nALTOPIANO BLU\11P.S.: PROF. OAK,\nvenite a trovarci!...",
  ["_OakSpeechText1"] = "Ciao a tutti!\nBenvenuti nel\11mondo dei POKéMON!\12Mi chiamo OAK!\nMa la gente mi\11chiama PROFESSORE\11POKéMON!",
  ["_OakSpeechText2A"] = "Questo mondo è\nabitato da creature\11chiamate POKéMON!",
  ["_OakSpeechText2B"] = "\nPer alcuni, i\nPOKéMON sono\11animali domestici.\nAltri li usano\11per lottare.\12Quanto a me...\11Studio i POKéMON\11di professione.",
  ["_OakSpeechText3"] = "{PLAYER}!\nLa tua leggenda\11POKéMON sta\11per iniziare!\12Ti attende un\nmondo di sogni\11e avventure!\11Avanti!",
  ["_OaksAideComeBackText"] = "Ah, capisco.\nQuando avrai\11{NUM:hOaksAideRequirement, 1, 3} specie,\ntorna a prendere\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "{PLAYER} ottiene\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Bene! Hai\ncatturato {NUM:hOaksAideNumMonsOwned, 1, 3} specie\11di POKéMON!\12Congratulazioni!\nEcco a te!",
  ["_OaksAideHiText"] = "Ciao! Ti ricordi\ndi me? Sono l'ASSIS-\11TENTE del PROF.OAK!\12Se catturi\n{NUM:hOaksAideRequirement, 1, 3} specie di POKéMON,\11dovrei darti\11{RAM:wOaksAideRewardItemName}!\12Bene, {PLAYER}!\nHai catturato almeno\11{NUM:hOaksAideRequirement, 1, 3} specie?",
  ["_OaksAideNoRoomText"] = "Oh! Vedo che\nnon hai spazio\11per {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Vediamo...\nOh! Hai catturato\11solo {NUM:hOaksAideNumMonsOwned, 1, 3} specie\11di POKéMON!\12Te ne servono\n{NUM:hOaksAideRequirement, 1, 3} per\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "Il PROF. OAK è\nun esperto di\11POKéMON!\12È ammirato da\nmolti allenatori!",
  ["_OaksLabGivePokeballsExplanationText"] = "\nQuando appare un\nPOKéMON selvatico,\nlotta contro di lui.\12Lanciagli una\nPOKé BALL per\ncatturarlo!\12Ma non funziona\nsempre!\12Un POKéMON in\nsalute può fuggire!\12Ci vuole anche\nfortuna!",
  ["_OaksLabLastMonText"] = "Questo è l'ultimo\nPOKéMON del\11PROF. OAK!",
  ["_OaksLabMonEnergeticText"] = "Questo POKéMON\nè pieno di energia!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Vieni a trovarmi\nogni tanto.\12Tienimi informato\nsui progressi del\11tuo POKéDEX!",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: {PLAYER}!\nCome sta il tuo\11POKéMON?\12Penso che ti\nvolgia molto bene!\12Sembri proprio\nun bravo allenatore!\12Cosa? Hai\nqualcosa per me?\12{PLAYER} consegna\nil PACCO di OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK: Piacere di\nvederti! Come\11procede il POKéDEX?\12Fammelo\ncontrollare!",
  ["_OaksLabOak1ParcelThanksText"] = "\nAh, sì! È la\nPOKé BALL che\11avevo ordinato!\12Grazie!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "{PLAYER}, i POKéMON\ndi tutto il mondo\11ti aspettano!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "OAK: {PLAYER},\nallenar i tuoi\11giovani POKéMON\11 lottando!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "OAK: Non scoprirai\ni segreti dei\11POKéMON solo\11guardandoli!\12Devi catturarli!\nUsa le POKé BALL.\12{PLAYER} riceve\n5 POKé BALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: {PLAYER},\nquale POKéMON\11vuoi?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: Se appare\nun POKéMON\11selvatico, il tuo\11potrà lottare!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "OAK: Calma\n{RIVAL}! Ne darò\11uno anche a te!",
  ["_OaksLabOakChooseMonText"] = "OAK: {RIVAL}?\nFammi pensare...\12Ah, sì! Ti avevo\ndetto di venire.\11Aspetta...\12{PLAYER}, tieni!\nCi sono 3 POKéMON!\12Sono dentro le\nPOKé BALL!\12Da giovane ero un\nottimo allenatore!\12Ora me ne sono\nrimasti 3. Te ne\11regalo uno. Quale\11scegli?",
  ["_OaksLabOakDontGoAwayYetText"] = "OAK: Ehi! Non\nte ne andare!",
  ["_OaksLabOakGotPokedexText"] = "OAK: {PLAYER} e\n{RIVAL}! Prendete\11i POKéDEX!\12{PLAYER} riceve\nil POKéDEX dal\11PROF. OAK!",
  ["_OaksLabOakIHaveARequestText"] = "OAK: Ah, già!\nVolevo chiedervi\11un favore.",
  ["_OaksLabOakMyInventionPokedexText"] = "Sul tavolo c'è\nil mio invenzione,\11il POKéDEX!\12Registrerà in\nautomatico i dati\11sui POKéMON visti\11o catturati!\12È una enciclopedia\nhi-tech!",
  ["_OaksLabOakThatWasMyDreamText"] = "Volevo creare\nuna guida di tutti\11i POKéMON del\11mondo... Era un\11mio sogno!\12Ma sono troppo\nvecchio e non\11posso farlo!\12Voglio che siate\nvoi a realizzare\11questo sogno!\12Forza, partite!\nSarà un'impresa\11leggendaria!",
  ["_OaksLabPokedexText"] = "Sembra un'enciclopedia,\nma le pagine\11sono bianche!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} riceve\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Beh!\nNon sono fantastico?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Nonno!\nSono stufo di\11aspettare!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Non sono\ncosì avaro!\12Forza, scegli\ntu per primo,\11{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Ciao\n{PLAYER}! Il nonno\11non c'è!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}:\nNonno!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "COSA?\nIncredibile!\12Il tuo POKéMON è\nmigliore del mio!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Allora\nprendo questo!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Aspetta\n{PLAYER}!\12Proviamo i nostri\nPOKéMON!\12Forza, lotta!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: Non\npreoccuparti, nonno!\12Ci penso io!\n{PLAYER}, sappi\11che non mi servi!\12Chiederò a mia\nsuggerire la MAPPA!\12E dirò di non\ndartene nessuna!\12Ah ah ah!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Il mio\nPOKéMON sembra\11molto più forte.",
