  ["_PewterCityMuseumSignText"] = "MUSEO SCIENTIFICO\ndi PLUMEOPOLI",
  ["_PewterCityPokecenterGuyText"] = "(Yawn)...\nQuando JIGGLYPUFF\11canta, i POKéMON\11si addormentano...\12Anche io...\n(Russamento)...",
  ["_PewterCityPoliceNoticeSignText"] = "AVVISO!\nDei ladri hanno\11rubato fossili\12dal M.TE MOON!\nAvvisate la POLIZIA\11di PLUMEOPOLI!",
  ["_PewterCitySignText"] = "PLUMEOPOLI\nLa città di\11roccia grigia.",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Sei stato al\nMUSEO?",
