  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Uso il REPELLENTE\nper tenere i\11POKéMON lontani\11dal mio giardino!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Esatto! È un\nlavoro duro!",
 ["_PewterCityTrainerTipsText"] = "CONSIGLI UTILI\nOgni POKéMON\11che lotta riceve\11ESPERIENZA!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Se hai fegato,\nsfida BROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Sei un allenatore?\nBROCK cerca nuovi\11avversari!\12Seguimi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\nÈ una MEDAGLIA\nufficiale della\11LEGA POKéMON!\12I POKéMON che la\npossiedono saranno\11molto più forti!\12E potrai usare\nFLASH in ogni\11momento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Ci sono allenatori\ndi ogni tipo!\12Sembri molto in\ngamba come\11allenatore!\12Vai alla PALESTRA\ndi CELESTE e metti\11alla prova le tue\11abilità!",
  ["_PewterGymBrockPreBattleText"] = "Sono BROCK!\nCAPOPALESTRA di\11PLUMEOPOLI!\12Credo nella grande\nresistenza della\11roccia e nella\11determinazione!\12Per questo tutti\ni miei POKéMON\11sono di tipo ROCCIA!\12Vuoi ancora\nsfidarmi? Ottimo!\12Mostrami cosa\nsai fare!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Non ho saputo\nvalutarti.\12Come prova della\ntua vittoria,\11ecco la MEDAGLIA\11ROCCIA!\12{PLAYER} ottiene\nla MEDAGLIA ROCCIA!",
  ["_PewterGymBrockWaitTakeThisText"] = "Aspetta! Porta\nquesto con te!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Sei piuttosto\nforte, ma non\11quanto BROCK!",
  ["_PewterGymCooltrainerMBattleText"] = "Alt, ragazzo!\nSei a anni luce\11dal poter sfidare\11BROCK!",
  ["_PewterGymCooltrainerMEndBattleText"] = "Mh!\nGli anni luce non\11sono tempo, misurano\11lo spazio!",
  ["_PewterGymGuideAdviceText"] = "Il 1° POKéMON\nche scende in lotta\11è il primo della\11LISTA POKéMON!\12Invertire l'ordine\npotrebbe facilitare\11i combattimenti!",
  ["_PewterGymGuideBeginAdviceText"] = "Molto bene!\nProcediamo!",
  ["_PewterGymGuideFreeServiceText"] = "È gratis!\nProcediamo!",
  ["_PewterGymGuidePostBattleText"] = "Lo sapevo!\nHai la stoffa\11del campione!",
  ["_PewterGymGuidePreAdviceText"] = "Posso dirti cosa\nserve per essere\11un campione di\11POKéMON!\12Non sono un\nallenatore, ma\11so come vincere!\12Lascia che ti\nguida alla vittoria!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} ottiene\nla MT34!",
  ["_PewterGymTM34NoRoomText"] = "Non hai spazio\nper questo!",
  ["_PewterMartSuperNerdText"] = "Potrebbero accadere\ncose belle se\11alleni in fretta\11i POKéMON, anche\11quelli più deboli!",
  ["_PewterMartYoungsterText"] = "Un vecchio\nmisterioso mi ha\11venduto questo\12strano POKéMON\npesce! È debole\11e costa 500$!",
  ["_PewterNidoranHouseLittleBoyText"] = "Siediti, NIDORAN!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Il nostro POKéMON\nè un forestiero,\11difficile da gestire.\12È un POKéMON\nscambiato con un\11altro giocatore.\12Cresce in fretta,\nma potrebbe\11ignorare un\11allenatore novizio\11in lotta!\12Magari avessimo\nqualche MEDAGLIA!",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Nidor!",
  ["_PewterPokecenterGentlemanText"] = "Cosa?\nIl TEAM ROCKET\11è al M.TE MOON?\11Sto parlando\11al telefono!\12Maledizione!",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Puff!\nPuuuff!",
  ["_PewterSpeechHouseGamblerText"] = "I POKéMON\nimparano nuove\11mosse crescendo!\12Ma certe mosse\ndevono impararle\11dall'allenatore!",
  ["_PewterSpeechHouseYoungsterText"] = "I POKéMON si\ncatturano più\11facilmente se\12sono feriti o\naddormentati!\12Ma non sempre\nè così!",
