  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\nè esausto!",
  ["_PokemonFanClubBagFullText"] = "Non hai spazio\nper questo!",
  ["_PokemonFanClubChairFinalText"] = "Ciao {PLAYER}!\nSei tornato per\11sapere altro sul\11mio POKéMON?\12No? Che peccato!",
  ["_PokemonFanClubChairmanIntroText"] = "Io sono il Presi-\ndente del Fan Club\11di POKéMON!\12Ho più di 100\nPOKéMON!\12Sono molto esigente\nin fatto di\11POKéMON!\12Beh...\12Sei qui per\nsaperne di più sui\11miei POKéMON?",
  ["_PokemonFanClubChairmanStoryText"] = "Benissimo!\nAscolta allora!\12Il mio preferito è\nRAPIDASH...\12È... grazioso...\naffettuoso... veloce\11e incredibile...\12Non trovi?... È\nsorprendente...\11simpatico...\11E gli voglio bene!\12Se lo abbracci...\nquando dorme...\11è così caldo...\11e coccoloso... è\11spettacolare...\12affascinante...\nOps! Guarda che\11ora! Parlo troppo!\12Grazie per avermi\nascoltato!\11Prendi questo!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\nScambialo per una\nBICICLETTA!\12Non importa, il mio\nFEAROW mi porta\11OVUNQUE IN VOLO!\12Non mi serve\nuna BICICLETTA!\12Spero ti piaccia\npedalare!",
  ["_PokemonFanClubNoStoryText"] = "Oh! Torna quando\nvuoi ascoltare\11la mia storia!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Il mio PIKACHU è\nil doppio più\11carino di quello!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Non ti piace la\nmeravigliosa coda\11del mio PIKACHU?",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPika, pika!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Il Presidente\nparla sempre di\11POKéMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Mio Dio!\nIl mio SEEL è\11molto più attraente!",
  ["_PokemonFanClubSeelFanNormalText"] = "Adoro il mio\nSEEL!\12Grida quando\nlo abbraccio!",
  ["_PokemonFanClubSeelText"] = "SEEL: Eeel!",
  ["_PokemonFanClubSign1Text"] = "Ascoltiamo con\nattenzione gli\11altri allenatori!",
  ["_PokemonFanClubSign2Text"] = "Se gli altri\nvanitosiscono, fallo\11anche tu!",
  ["_PokemonFightingFitText"] = "Grazie! I tuoi\nPOKéMON sono\11in forma perfetta!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Una chiave?\nNon so proprio di\11cosa tu stia parlando!",
  ["_PokemonMansion1FScientistBattleText"] = "Chi sei tu?\nQui non dovrebbe\11esserci nessuno.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Ahi!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion1FSwitchPressedText"] = "E chi non\nlo farebbe?",
  ["_PokemonMansion1FSwitchText"] = "Un interruttore\nsegreto.\12Lo premo?",
  ["_PokemonMansion2FDiary1Text"] = "Diario:\n5 luglio.\11Guyana,\11Sudamerica.\12Un nuovo tipo di\nPOKéMON è stato\11scoperto nel\11cuore della giungla.",
  ["_PokemonMansion2FDiary2Text"] = "Diario:\n10 luglio.\11Abbiamo chiamato\11questo nuovo\11POKéMON, MEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Gli interruttori\naprono e chiudono\11alternativamente\11i gruppi di porte!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Non so uscire!\nQuesto vecchio\11posto è un enorme\11labirinto!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Oh no!\nIl mio bottino!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion2FSwitchPressedText"] = "E chi non lo farebbe?",
  ["_PokemonMansion2FSwitchText"] = "Un interruttore\nsegreto!\12Lo premo?",
  ["_PokemonMansion3FDiaryText"] = "Diario:\n6 febbraio.\11MEW ha dato alla luce\11un piccolo.\12Lo abbiamo chiamato\nMEWTWO.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Bloccato?\nButtati giù di lì!",
  ["_PokemonMansion3FScientistBattleText"] = "Il mio maestro\nha vissuto qui\11tempo fa.",
  ["_PokemonMansion3FScientistEndBattleText"] = "Uau!\nImpressionante!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Chissà dove\nè finito il mio\11collega.",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Questo posto è...\nGigantesco!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "\nAhi!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Puoi raccogliere\noggetti da terra.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh-oh! Dove\nmi trovo ora?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Ops!",
 ["_PokemonMansionB1FDiaryText"] = "Diario:\n1 settembre.\nMEWTWO è troppo\12potente.\nNon siamo riusciti\na contenere i suoi\11istinti malvagi.",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Adoro questo posto!\nÈ perfetto per\11i miei studi!",
  ["_PokemonMansionB1FScientistBattleText"] = "Questo posto è\nideale per un\11laboratorio.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "\nPer cosa era?",
  ["_PokemonSellingGreetingText"] = "Cosa vorresti\nvendere?",
  ["_PokemonStuffText"] = "Uau! Un sacco\ndi articoli sui\11POKéMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Sono venuto a\npregare per il mio\11CLEFAIRY.\nSniff! Non riesco\11a smettere di\11piangere...",
  ["_PokemonTower1FChannelerText"] = "Sono una MEDIUM!\nCi sono spiriti\11molto turbati!",
  ["_PokemonTower1FGirlText"] = "Il mio GROWLITHE...\nPerché sei dovuto\11morire?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Sei venuto a\nrendergli omaggio?\12Sii benedetto!",
  ["_PokemonTower1FReceptionistText"] = "La TORRE POKéMON\nè stata eretta in\11memoria dei POKéMON\11che sono morti.",
  ["_PokemonTower2FChannelerText"] = "Non siamo riusciti\nneanche a identificare\11gli SPETTRI!\nLo SCOPE SILPH\11potrebbe smascherarli.",
  ["_PokemonTower2FRivalDefeatedText"] = "Cosa?\nQuanto sei scarso!\12E dire che ti\navevo preso sul\11serio!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Come va il POKéDEX?\nHo appena catturato\11un CUBONE!\12Non ho ancora trovato\nil MAROWAK adulto!\11Non credo ne sia\11rimasto alcuno!\12Meglio che vada!\11Ho molto da fare!\12A presto!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Guarda\nquanto fanno schifo\11i tuoi POKéMON!\12Allenali un po'!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: Ehi,\n{PLAYER}! Che fai\11da queste parti?\12I tuoi POKéMON non\npossono morire!\12Al massimo posso\nsconfiggerli!\11Forza, ragazzo!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "Gli SPETTRI si\nriconoscono con lo\11SCOPE SILPH.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg... Aaa...\nUuuu... graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Uau!\nSono salvo!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Scusa!\nEro posseduto!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kikiki...\nGaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Mhm?\nMa cosa sto facendo?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Anche i miei amici\nerano posseduti!",
  ["_PokemonTower3FChanneler3BattleText"] = "Fuori, spirito\ninfernale!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Lo spirito\nè andato via!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Devo averlo\nsognato...",
  ["_PokemonTower4FChanneler1BattleText"] = "Uno SPETTRO!\nNo! Guaaah!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Dov'è\nlo SPETTRO?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Non possiamo\nsvelare l'identità\11degli SPETTRI!",
  ["_PokemonTower4FChanneler2BattleText"] = "Maledetto!\nGuaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Cosa!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Che le anime defunte\ndei POKéMON riposino\11in pace!",
  ["_PokemonTower4FChanneler3BattleText"] = "Uu Uu Uu...\nNon mi batterai!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Eh?\nChi? Cosa?",
  ["_PokemonTower5FChanneler1Text"] = "Vieni qui, ragazzo!\nHo sigillato questo\11luogo con la magia\12bianca! Qui puoi\nriposare!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Ero posseduto!",
  ["_PokemonTower5FChanneler2BattleText"] = "Dammi...\nla tua...\nanima...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Gasp!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Ero posseduto!",
  ["_PokemonTower5FChanneler3BattleText"] = "Vieni...\ncon...\nnoi...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Che\nincubo!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Ho ripreso\ncoscienza!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombi!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Ah?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Nonostante il mio\nallenamento sono\11stato catturato\11dagli spiriti!",
  ["_PokemonTower5FChanneler5BattleText"] = "Oooo!...\nUuuu!....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Uuuu!",
  ["_PokemonTower5FPurifiedZoneText"] = "Sei entrato in una\nzona di purezza\11e sicurezza!\12I POKéMON di\n{PLAYER} sono\11guariti!",
  ["_PokemonTower6FBeGoneText"] = "Via...\nIntrusi...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Mi sento anemica\ne debole...",
  ["_PokemonTower6FChanneler1BattleText"] = "Da... mmi...\nsangue...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Grrr!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "Non ci credo!\nEra un spirito\11maligno!",
  ["_PokemonTower6FChanneler2BattleText"] = "Uuff... Guaa!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Qualcosa\nè caduto!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Che sta succedendo\nqui?",
  ["_PokemonTower6FChanneler3BattleText"] = "Ki... ki...\nki... ki... ki!!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Kiii!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Quello SPETTRO era\nil turbato spirito\11della madre di CUBONE!",
  ["_PokemonTower6FSoulWasCalmedText"] = "Lo spirito della\nmadre riposa in\11pace. E se n'è\11andato nell'aldilà!",
  ["_PokemonTower7FMrFujiRescueText"] = "SR. FUJI: Eh?\nSei venuto a\11salvarmi?\12Grazie! Ma sono qui\nper mia spontanea\11volontà.\12Sono venuto a\ncalmare lo spirito\11della madre di CUBONE.\12Credo che lo\nspirito di MAROWAK\11sia andato nell'aldilà.\12Ti ringrazio per\nil nobile gesto!\12Accompagnami a casa,\nnella CASA POKéMON\11ai piedi di questa\11torre.",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Dimenticherò\ntutto questo!",
  ["_PokemonTower7FRocket1BattleText"] = "Che vuoi?\nChe ci fai qui?",
  ["_PokemonTower7FRocket1EndBattleText"] = "\nMi arrendo!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "I POKéMON servono\nsolo per fare soldi!\12Non impicciarti\nnei nostri affari!",
  ["_PokemonTower7FRocket2BattleText"] = "Questo vecchio\nè venuto a lagnarsi\11che facevamo del\11male ai deboli POKéMON.\12Ne stiamo discutendo\nda adulti!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Per favore!\nBasta!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Non l'avrai vinta\ncosì facilmente!",
  ["_PokemonTower7FRocket3BattleText"] = "Non salverai\nnessuno, moccioso!",
  ["_PokemonTower7FRocket3EndBattleText"] = "\nNon lottare contro\11di noi, il\11TEAM ROCKET!",
  ["_PoliwagDexEntry"] = "Le piccole nuove\nzampe non gli\npermettono di correre.\12Sembra preferire\nil nuoto alla\nposizione eretta.",
  ["_PoliwhirlDexEntry"] = "In grado di vivere\ndentro o fuori\ndall'acqua. Fuori\12dalacqua suda\nper mantenere il\ncorpo viscido.",
  ["_PoliwrathDexEntry"] = "Nuotatore esperto\nsia a rana che\na stile libero.\12Batte facilmente\nogni nuotatore\numano.",
  ["_PonytaDexEntry"] = "I suoi zoccoli sono\n10 volte più duri\ndel diamante.\12Può calpestare\nqualsiasi cosa\nin un lampo.",
  ["_PoofText"] = " Puff!",
  ["_PorygonDexEntry"] = "Un POKéMON\nformato da\ncodici di\12programmazione.\nSi muove libero\nnel cyberspazio.",
  ["_PotionText"] = "{RAM:wNameBuffer}\nrecupera {NUM:wHPBarHPDifference, 2, 3} PS!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Zap Zap!",
  ["_PrimeapeDexEntry"] = "Sempre furioso e\ntenace con i\nsuoi calci.\12Insegue la preda\nfinché non la\ncattura.",
  ["_PushStartText"] = "Premi START per\naprire il MENU!",
  ["_RaichuDexEntry"] = "La lunga coda\ngli serve per\nproteggersi dal\12suo stesso potere\ne dall'alto\nvoltaggio.",
  ["_RaisePPWhichTechniqueText"] = "Aumentare PP di\nquale mossa?",
  ["_RanAwayScaredText"] = "{TARGET}\nè fuggito impaurito!",
  ["_RanFromBattleText"] = "{USER}\nè fuggito dalla lotta!",
  ["_RapidashDexEntry"] = "Molto competitivo,\ninsegue qualsiasi\ncosa si muova\12rapidamente,\nsperando di batterla.",
  ["_RareCandyText"] = "{RAM:wNameBuffer} sale\nal livello {NUM:wCurEnemyLevel, 1, 3}!",
  ["_RaticateDexEntry"] = "Usa i baffi per\nmantenere l'equilibrio.\12Se glieli tagliano,\nsembra rallentare.",
  ["_RattataDexEntry"] = "Morde ogni cosa\nquando attacca.\nPiccolo e molto\12rapido, si vede\nfacilmente in\nmolti luoghi.",
  ["_RedBedroomSNESText"] = "{PLAYER} gioca\nalla Super Nintendo!\12...Bene!\nÈ meglio andare!",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMÁ: Benissimo!\nTu e i tuoi\11POKéMON siete\11in forma! Abbi cura\11di te!",
  ["_RedsHouse1FMomWakeUpText"] = "MAMÁ: Bene.\nTutti i bambini\11lasciano la casa\11un giorno. La vita è così!\12Il nostro vicino,\nil PROF. OAK,\11voleva vederti.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMÁ: {PLAYER}!\nDovresti prenderti\11un po' di riposo.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "C'è un film in TV!\n4 ragazzi camminano\11lungo i binari.\12Dovrei proprio\nandare!",
  ["_RedsHouse1FTVWrongSideText"] = "Ahi! Ho guardato\ndal lato sbagliato.",
  ["_ReflectGainedArmorText"] = "{USER}\nguadagna protezione!",
  ["_RegainedHealthText"] = "{USER}\nè guarito!",
  ["_ReleaseWhichMonText"] = "Quale POKéMON\nvuoi liberare?",
  ["_RepelWoreOffText"] = "L'effetto del\nREPELLENTE\11è svanito.",
 ["_RequireCoinCaseText"] = "È richiesto il\nSALVADANAIO!",
  ["_RestorePPWhichTechniqueText"] = "Ripristinare PP di\nquale mossa?",
  ["_ReviveText"] = "{RAM:wNameBuffer}\nrivitalizzato!",
  ["_RhydonDexEntry"] = "Protetto da una\npelle a scudo, può\nvivere nella lava\12liquida a una\ntemperatura di\n3600 gradi.",
  ["_RhyhornDexEntry"] = "Ha ossa mille volte\npiù robuste di\nquelle umane.\12Famoso per la\nsua grande forza.",
  ["_Rival1WinText"] = "{RIVAL}: Sì!\nNon sono fantastico?",
  ["_RivalDefeatedText"] = "NO!\nImpossibile! Mi\11hai sconfitto!\12Dopo tanti sforzi\nper diventare\nCAMPIONE DELLA LEGA!\12Il mio regno è\ngià finito?\nNon è giusto!",
  ["_RivalVictoryText"] = "Ah ah ah!\nHo vinto io!\12{PLAYER}, sono\ntroppo bravo per te!\12Sei arrivato fino\na me, {RIVAL},\11il genio dei POKéMON!\12Ben fatto, perdente!\nAh ah ah!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Ho visto un MACHOP\nin questo tunnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Ehi! Non fare\nsciocchezze nel\11buio!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "\nC'era troppo\nbuio!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = " Sembravi tanto\ncarino e inerme!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Sono venuta qui\nper i POKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "\nHo esaurito i\nPOKéMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Uff! Sto sudando\nsette camicie!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Hai dei POKéMON!\nIniziamo!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "\nCi vai pesante!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Attento a ONIX.\nPotrebbe stritolarti\11le ossa!",
  ["_RockTunnel1FHiker1BattleText"] = "Questo tunnel buio\nè molto lungo,\11ragazzo!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Uau!\nVinci tu!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Quel POKéMON\naddormentato al\11PERCORSO 12 mi ha\11costretto a deviare.",
  ["_RockTunnel1FHiker2BattleText"] = "Mh. Forse mi sono\nperso...",
  ["_RockTunnel1FHiker2EndBattleText"] = "\nTranquillo!\nChe faccio? Dove\11si esce?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Hai la stoffa\ndel buon montanaro!",
  ["_RockTunnel1FHiker3BattleText"] = "Gli estranei come\nte dovrebbero\11portarmi rispetto!",
  ["_RockTunnel1FHiker3EndBattleText"] = "\nMi arrendo!",
  ["_RockTunnel1FSignText"] = "TÚNEL ROCA:\nCELESTE - LAVANDA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Prenderò un\nZUBAT lungo la\11strada!",
  ["_RockTunnel1FSuperNerdBattleText"] = "Lotta POKéMON!\nPronto? VIA!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "\nFine della\npartita!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Voglio tornare\na casa!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "I montanari\nsegnano la strada\11con dei ramoscelli.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "\nOh! Ho fatto del\nmioglior del mio!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Adoro i POKéMON\npiccoli! Quelli\11grandi fanno orrore!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Non vengo spesso\nqui, ma lotterò\11con te!",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "\nOh! Ho perso!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Preferisco la\nforza perché non\11mi va di pensare!",
  ["_RockTunnelB1FHiker1BattleText"] = "Ah ah! Credi di\npoter battermi?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Ops!\nLivello muscolare:\11Zero!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "In montagna ci\nsono spesso POKéMON\11di tipo ROCCIA.",
  ["_RockTunnelB1FHiker2BattleText"] = "Le mie tecniche\ndi POKéMON ti\11faranno piangere!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "\nMi arrendo!\nLe tue tecniche\11sono migliori!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Crescerò i miei\nPOKéMON affinché\11distruggano i tuoi!",
  ["_RockTunnelB1FHiker3BattleText"] = "Lanciami il tuo\nattacco migliore!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "\nForza, avanti!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Quando finisci\nil POKéDEX, me\11lo presteresti?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Hai un POKéDEX?\nNe voglio uno\11anch'io!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "\nGrr! Quanta\ninvidia!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "I giocatori in\ncostume si vestono\11da POKéMON per\11divertimento.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Cosa sai di quei\ngiocatori in\11costume?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Beh,\ntutto qui.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Sono un artista,\nnon un guerriero.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Quando sono a\ncasa, disegno i\11POKéMON.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Uffa!\nSono esausto!",
  ["_RockTunnelPokecenterFisherText"] = "Ho venduto una\nPEMPA inutile\11per 5000$!",
  ["_RockTunnelPokecenterGentlemanText"] = "I POKéMON di\ncerti elementi\11sono più forti di\11altri!",
  ["_RockTunnelPokecenterGuyText"] = "Dicono che ci\nsiano SPETTRI a\11PUEBLO LAVANDA!",
  ["_RocketHide3AfterBattleText3"] = "Avanti, va'!\nMa ti servirà la\11CHIAVE ASCENSORE!",
  ["_RocketHideout3BattleText"] = "Ci hanno avvisati\ndall'alto che\11arrivavi!",
  ["_RocketHideout3EndBattleText3"] = "Cosa?\nHo perso? NO!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Vuoi lottare\ncontro il\11TEAM ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Chi sei tu?\nE come sei\11arrivato qui?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Ahi!\nHo perso!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Non l'avrai vinta,\nmoccioso!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Hai mandato all'aria\ni nostri piani!",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "\nArrostito!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "Lo SCOPE SILPH?\nNon so dove sia!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Allarme!\nC'è un intruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Non ce l'ho\nfatta!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "D'accordo, parlo!\nPrendi l'ascensore\11per il CAPO!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Perché sei\nvenuto qui?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Questo non\nservirà!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Oh no, quella lotta\nha aperto la porta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Ti sei perso,\npiccoletto?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "\nPerché...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "Il quartier generale\ndel TEAM ROCKET ha\114 piani sotterranei.\11Arriverai al CAPO?",
  ["_RocketHideoutB2FRocketBattleText"] = "Il CAPO ha detto\nche si vedono i\11fantasmi con lo\11SCOPE SILPH!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "\nMi arrendo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "Lo SCOPE SILPH?\nLa macchina rubata\11dal CAPO. Deve\11essere qui vicino.",
  ["_RocketHideoutB3FRocket1BattleText"] = "Smettila di impicciarti\nnegli affari del\11TEAM ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Uff!\nMi hanno steso!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Vedo che hai\nallenato i tuoi\11POKéMON con cura.\12Un ragazzino come\nte non capirebbe\11i miei piani!\12Per questa volta\nti lascerò andare!\12Spero ci\nrivedremo.",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Mh! Sono molto\ncolpito che tu sia\11arrivato fin qui!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "COSA?\nÈ impossibile!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Ce l'hai con il\nTEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Ti conosco! Sei\ntu che hai rovinato\11i nostri piani al\11M.TE MOON!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "\nArrostito\ndi nuovo!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "CAPO! Perdonatemi,\nho fallito!",
  ["_RocketHideoutB4FRocket2BattleText"] = "Non vedi la bellezza\ndei nostri atti\11malvagi?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Ahi ahi ahi!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Oh no! Ho perso\nla CHIAVE ASCENSORE!",
  ["_RocketHideoutB4FRocket3BattleText"] = "L'ascensore non va?\nChi ha la CHIAVE\11ASCENSORE?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "No!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Sembra richiedere\nuna chiave!",
  ["_RoseText"] = "è cresciuto!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Ho visto alcuni\nMANIACI POKéMON\11da queste parti.",
  ["_Route10CooltrainerF1BattleText"] = "Sono stato in\ndiversi POKéMON\11GYM... E ho sempre\11perso!",
  ["_Route10CooltrainerF1EndBattleText"] = "\nHo perso di nuovo!",
  ["_Route10CooltrainerF2AfterBattleText"] = "Questi POKéMON\nsono così robusti!\11Dovrebbe essercene\11uno rosa con dei\11bei fiori!",
  ["_Route10CooltrainerF2BattleText"] = "Mi sento debole\ndopo la scalata!",
  ["_Route10CooltrainerF2EndBattleText"] = "Non ne ho\nvoglia!",
  ["_Route10Hiker1AfterBattleText"] = "Et-ciù!\nEt-ciù!\11(Tossisce)...\11(Piagnucola)...",
  ["_Route10Hiker1BattleText"] = "Et-et-et-et-ciù!",
  ["_Route10Hiker1EndBattleText"] = "\nEt-ciù! Non sto\11ridendo! È\11allergia!\11Et-et-ciù!",
  ["_Route10Hiker2AfterBattleText"] = "L'aria di montagna\nmi stordisce!",
  ["_Route10Hiker2BattleText"] = "Adoro l'aria\ndi montagna!",
  ["_Route10Hiker2EndBattleText"] = "Questo mi ha\nschiarito le\11idee!",
  ["_Route10PowerPlantSignText"] = "CENTRALE ELETTRICA",
  ["_Route10RockTunnelSignText"] = "TUNNEL ROCA",
  ["_Route10SuperNerd1AfterBattleText"] = "A casa ho altri\nPOKéMON rarissimi!",
  ["_Route10SuperNerd1BattleText"] = "Sei anche tu un\nMANIACO POKéMON?\11Vuoi vedere la mia\11collezione?",
  ["_Route10SuperNerd1EndBattleText"] = "\nCosa! Non sono\11arrabbiato!",
  ["_Route10SuperNerd2AfterBattleText"] = "Non mi piaci\nquando vinci!",
  ["_Route10SuperNerd2BattleText"] = "Ehi, ragazzo!\nVuoi vedere i\11miei POKéMON?",
  ["_Route10SuperNerd2EndBattleText"] = "Oh\nno! I miei POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "GROTTA DI DIGLETT",
  ["_Route11Gambler1AfterBattleText"] = "I POKéMON sono\nvita! E vivere\11è giocare!",
  ["_Route11Gambler1BattleText"] = "Vinci, perdi o\npareggia!",
  ["_Route11Gambler1EndBattleText"] = "Bene!\nHai vinto!",
  ["_Route11Gambler2AfterBattleText"] = "Non puoi fare il\ncovardo nel mondo\11dei POKéMON!",
  ["_Route11Gambler2BattleText"] = "Competizione!\nNon mi stanco\11mai di competere!",
  ["_Route11Gambler2EndBattleText"] = "Ho avuto\nuna chance!",
  ["_Route11Gambler3AfterBattleText"] = "Hai avuto molta\nfortuna!",
  ["_Route11Gambler3BattleText"] = "AHAHAH! Non ho\nmai perso!",
  ["_Route11Gambler3EndBattleText"] = "\nÈ la prima volta\11che perdo!",
  ["_Route11Gambler4AfterBattleText"] = "Hai avuto molta\nfortuna.",
  ["_Route11Gambler4BattleText"] = "È la prima volta\nche vinco...",
  ["_Route11Gambler4EndBattleText"] = "Me lo\nspettavo...",
  ["_Route11Gate1FGuardText"] = "Quando catturi\nmanti POKéMON,\11è dura dare i\11soprannomi?\12A PUEBLO LAVANDA\nc'è un esperto che\11valuta i soprannomi\11e ti aiuta a\11cambiarli!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Hai guardato nel\ncannocchiale.\12Che bel panorama!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Hai guardato nel\ncannocchiale.\12Un grosso POKéMON\nsta dormendo\11sul sentiero!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Ci sono oggetti\ninvisibili a terra.\12Il DETECTOR li\nsegnala se sono\11vicini, ma non\11indica il punto\11esatto!",
  ["_Route11Gate2FRightBinocularsText"] = "Hai guardato nel\ncannocchiale.\12Puoi andare da\nCELESTE a PUEBLO\11LAVANDA attraverso\11il TUNNEL ROCA!",
  ["_Route11SuperNerd1AfterBattleText"] = "Dite a tutti\ndi risparmiare\11energia!",
  ["_Route11SuperNerd1BattleText"] = "Attenzione! Sto\nposando dei cavi!",
  ["_Route11SuperNerd1EndBattleText"] = "Molto\nelettrizzante!",
  ["_Route11SuperNerd2AfterBattleText"] = "Meglio tornare\nal lavoro!",
  ["_Route11SuperNerd2BattleText"] = "Attenzione a\nquei cavi!",
  ["_Route11SuperNerd2EndBattleText"] = "Uau!\nChe scossa!",
  ["_Route11Youngster1AfterBattleText"] = "Ho fatto del\nmio meglio! E non\11me ne pento!",
  ["_Route11Youngster1BattleText"] = "Facciamo sul\nserio, niente\11trucchi!",
  ["_Route11Youngster1EndBattleText"] = "Cosa?\nNon può essere!",
  ["_Route11Youngster2AfterBattleText5"] = "Che vuoi?\nLasciami in pace!",
  ["_Route11Youngster2BattleText"] = "Sono un nuovo\nallenatore! Ma\11credo di poter\11vincere!",
  ["_Route11Youngster2EndBattleText"] = "I miei\nPOKéMON\11hanno perso!",
  ["_Route11Youngster3AfterBattleText"] = "C'è un grosso\nPOKéMON che scende\11dalle montagne.\12È fortissimo,\nma prima bisogna\11prenderlo.",
  ["_Route11Youngster3BattleText"] = "Sono il migliore\ndella classe!",
  ["_Route11Youngster3EndBattleText"] = "\nMaledizione!\nI miei POKéMON\11devono crescere!",
  ["_Route11Youngster4AfterBattleText"] = "Meglio trovarne\ndi più forti!",
  ["_Route11Youngster4BattleText"] = "I miei POKéMON\ndovrebbero essere\11pronti!",
  ["_Route11Youngster4EndBattleText"] = "Sono\ntroppo giovane!",
 ["_Route12CooltrainerMAfterBattleText"] = "Avrei potuto\ntrasformare i miei\11POKéMON con una\11PIETRALUNARE!",
  ["_Route12CooltrainerMBattleText"] = "Hai trovato una\nPIETRALUNARE?",
  ["_Route12CooltrainerMEndBattleText"] = "\nAhi!",
  ["_Route12Fisher1AfterBattleText"] = "Alt! La mia lenza\nè impigliata!",
  ["_Route12Fisher1BattleText"] = "Bene! Ha\nabboccato qualcosa!",
  ["_Route12Fisher1EndBattleText"] = "\nBah! Era un\npesciolino!",
  ["_Route12Fisher2AfterBattleText"] = "Con una CANNA\nmigliore potrei\11pescare POKéMON\11più forti!",
  ["_Route12Fisher2BattleText"] = "Abbi pazienza!\nLa pesca richiede\11tempo!",
  ["_Route12Fisher2EndBattleText"] = "Quello mi è\nsfuggito!",
  ["_Route12Fisher3AfterBattleText"] = "Mi hai battuto\ncon i POKéMON,\11ma io sono un\11pescatore esperto!",
  ["_Route12Fisher3BattleText"] = "Il PESCATORE PAZZO\ncontro il FAN\11DI POKéMON!",
  ["_Route12Fisher3EndBattleText"] = "Questo è troppo!",
  ["_Route12Fisher4AfterBattleText"] = "Va bene.\nPerdere non mi\11importa più.",
  ["_Route12Fisher4BattleText"] = "Preferirei\nlavorare!",
  ["_Route12Fisher4EndBattleText"] = "Non è\nfacile...",
  ["_Route12Fisher5AfterBattleText"] = "È facile pescare\nMAGIKARP, sono\11così deboli!",
  ["_Route12Fisher5BattleText"] = "Non sai mai\ncosa puoi pescare!",
  ["_Route12Fisher5EndBattleText"] = "\nHo perso!",
  ["_Route12Gate1FGuardText"] = "C'è una bella\nvista da lassù.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} ottiene\nla MT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "La MT39 contiene\nATTACCO RAPIDO!\12È precisissima.\nUsala negli scontri\11che non puoi\11permetterti di perdere.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Non hai spazio\nper questo!",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Le ceneri dei miei\nPOKéMON sono\11custodite alla\11TORRE POKéMON.\12Puoi tenere la\nmia MT, non mi\11serve più...",
  ["_Route12Gate2FLeftBinocularsText"] = "Hai guardato nel\ncannocchiale.\12Un uomo sta\npescando!",
  ["_Route12Gate2FRightBinocularsText"] = "Hai guardato nel\ncannocchiale.\12È la TORRE\nPOKéMON!",
  ["_Route12SignText"] = "PERCORSO 12:\nLAVANDA a nord",
  ["_Route12SnorlaxCalmedDownText"] = "SNORLAX si è\ncalmato e, dopo un\11sbadiglio, è tornato\11tra i monti!",
  ["_Route12SnorlaxText"] = "Un POKéMON\naddormentato blocca\11la strada!",
  ["_Route12SnorlaxWokeUpText"] = "SNORLAX si è\nsvegliato!\nSi è infuriato ed\11attacca con rabbia!",
  ["_Route12SportFishingSignText"] = "ZONA DI PESCA",
  ["_Route12SuperNerdAfterBattleText"] = "L'acqua conduce\nl'elettricità.\12Dovresti riuscire\na catturare i\11POKéMON marini!",
  ["_Route12SuperNerdBattleText"] = "Sono un esperto\ndi elettricità!",
  ["_Route12SuperNerdEndBattleText"] = "\nFinita!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il fratello\ndel GURU PESCATORE!\12Adoro pescare!\nTi piace pescare?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\nLa pesca è uno\nstile di vita!\12Dal mare ai fiumi,\npesca il più grande!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Oh no!\nAvevo un regalo\11per te, ma non\11hai spazio!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Ottimo! Mi piace\nil tuo stile!\12Prendi questa e\npesca, giovanotto!\12{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Sono molto\ndeluso...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Ciao, {PLAYER}!\nUsa la SUPERCANNA\11ovunque ci sia\nacqua! Puoi trovare\11molti POKéMON.\12Pesca ogni volta\nche puoi!",
  ["_Route13Beauty1AfterBattleText"] = "Chi è più forte,\nun POKéMON maschio\11o una femmina?",
  ["_Route13Beauty1BattleText"] = "Certo che gioco\ncon te!",
  ["_Route13Beauty1EndBattleText"] = "Oh!\nCome sei rude!",
  ["_Route13Beauty2AfterBattleText"] = "Non so nulla di\nPOKéMON! Mi piacciono\11quelli fighi!",
  ["_Route13Beauty2BattleText"] = "Vuoi fare una\nlotta POKéMON\11con me?",
  ["_Route13Beauty2EndBattleText"] = "\nÈ già finita?",
  ["_Route13BikerAfterBattleText"] = "Dimenticami!",
  ["_Route13BikerBattleText"] = "Che figata\nguardi?",
  ["_Route13BikerEndBattleText"] = "Acciderboli!\nHo sbandato!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Voglio diventare\nuna grande allenatrice.\12Lavorerò sodo.",
  ["_Route13CooltrainerF1BattleText"] = "Dicono che sono\nmolto brava per\11essere una ragazza!",
  ["_Route13CooltrainerF1EndBattleText"] = "\nOh! Ho perso!",
  ["_Route13CooltrainerF2AfterBattleText"] = "So che hai preso\nquelle MEDAGLIE dai\11CAPIPALESTRA!",
  ["_Route13CooltrainerF2BattleText"] = "Che figate sono\nle tue MEDAGLIE!",
  ["_Route13CooltrainerF2EndBattleText"] = "Non è\nbastato!",
  ["_Route13CooltrainerF3AfterBattleText"] = "Devi far lottare\ni tuoi POKéMON\11per farli crescere!",
  ["_Route13CooltrainerF3BattleText"] = "I miei simpatici\nPOKéMON vogliono\11conoscerti.",
  ["_Route13CooltrainerF3EndBattleText"] = "\nUau! Mi hai\11distrutto!",
  ["_Route13CooltrainerF4AfterBattleText"] = "Il CARBOHYDRATE\nha aumentato la\11VELOCITÀ dei\11miei POKéMON.",
  ["_Route13CooltrainerF4BattleText"] = "Una volta ho trovato\nCARBOHIDRATO in\11una grotta!",
  ["_Route13CooltrainerF4EndBattleText"] = "Ho fatto un\nfallimento!",
  ["_Route13CooltrainerM1AfterBattleText"] = "I miei POKéMON\nsembrano felici\11anche se hanno\11perso.",
  ["_Route13CooltrainerM1BattleText"] = "I miei POKéMON\nuccello vogliono\11lottare!",
  ["_Route13CooltrainerM1EndBattleText"] = "\nLa mia combinazione\11di uccelli ha\11perso?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Ho perso. Credo\nche VOLERÒ a casa.",
  ["_Route13CooltrainerM2BattleText"] = "Il vento spira\nverso di me!",
  ["_Route13CooltrainerM2EndBattleText"] = "Il vento è\ncambiato!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Vorrei volare\ncome PIDGEY e\11PIDGEOTTO...",
  ["_Route13CooltrainerM3BattleText"] = "Adoro i POKéMON\nuccello!",
  ["_Route13CooltrainerM3EndBattleText"] = "Ho esaurito\nl'energia!",
  ["_Route13SignText"] = "PERCORSO 13:\nPONTE SILENZIO\11a nord",
  ["_Route13TrainerTips1Text"] = "CONSIGLI UTILI\nGuarda alla\11sinistra di\11quel palo!",
  ["_Route13TrainerTips2Text"] = "CONSIGLI UTILI\nUsa SELECT per\nspostare gli strumenti\11nella finestra\11STRUMENTI!",
  ["_Route14Biker1AfterBattleText"] = "Che c'è, che c'è?\nChe vuoi?",
  ["_Route14Biker1BattleText"] = "Forza, forza!\nAvanti!",
  ["_Route14Biker1EndBattleText"] = "Arg!\nHo perso! Vattene!",
  ["_Route14Biker2AfterBattleText"] = "Allenare i POKéMON\nè una noia mortale!",
  ["_Route14Biker2BattleText"] = "Perfetto! Così\npasso il tempo!",
  ["_Route14Biker2EndBattleText"] = "Cosa?\nTu!?",
  ["_Route14Biker3AfterBattleText"] = "Ottimo! I tuoi\nPOKéMON sono\11fortissimi!\12La forza spacca,\ne tu lo sai!",
  ["_Route14Biker3BattleText"] = "Veniamo qui perché\nc'è più spazio!",
  ["_Route14Biker3EndBattleText"] = "\nAnnientato!",
  ["_Route14Biker4AfterBattleText"] = "Lo sai già chi\nvincerebbe se\11ci picchiassimo!",
  ["_Route14Biker4BattleText"] = "Vuoi lottare\ncon i POKéMON?\11E va bene!",
  ["_Route14Biker4EndBattleText"] = "\nPolverizzato!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Hai delle MN, vero?\nI POKéMON non\11le dimenticheranno\11mai.",
  ["_Route14CooltrainerM1BattleText"] = "Usa le MT per\ninsegnare mosse\11forti ai POKéMON!",
  ["_Route14CooltrainerM1EndBattleText"] = "Non ho fatto\nun granché!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Devono imparare\nattacchi migliori.",
  ["_Route14CooltrainerM2BattleText"] = "I miei POKéMON\nuccello dovrebbero\11poter lottare.",
  ["_Route14CooltrainerM2EndBattleText"] = "Non sono\npronto!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Insegna ai POKéMON\nattacchi dello\11stesso tipo per\11più potenza.",
  ["_Route14CooltrainerM3BattleText"] = "Vendono MT ad\nAZZURROPOLI! Ma\11pochi hanno le MN!",
  ["_Route14CooltrainerM3EndBattleText"] = "Ahi!\nChe male!",
  ["_Route14CooltrainerM4AfterBattleText"] = "Adoro i POKéMON\nuccello!",
  ["_Route14CooltrainerM4BattleText"] = "Hai insegnato a\nVOLARE ai tuoi\11uccelli?",
  ["_Route14CooltrainerM4EndBattleText"] = "È finito tra\nle fiamme!",
  ["_Route14CooltrainerM5AfterBattleText"] = "I 3 POKéMON\nleggendari sono\11uccelli rapaci.",
  ["_Route14CooltrainerM5BattleText"] = "Hai sentito parlare\ndei POKéMON\11leggendari?",
  ["_Route14CooltrainerM5EndBattleText"] = "Cosa?\nCome ho fatto\11a perdere?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Non è poi così\nimportante vincere\11o perdere!",
  ["_Route14CooltrainerM6BattleText"] = "Non mi va!\nMa va bene.",
  ["_Route14CooltrainerM6EndBattleText"] = "\nLo sapevo!",
  ["_Route14SignText"] = "PERCORSO 14:\nFUCSIAPOLI a ovest",
  ["_Route15Beauty1AfterBattleText"] = "Ti perdono!\nSei così carino!",
  ["_Route15Beauty1BattleText"] = "Oh! Sei così\ncarino!",
  ["_Route15Beauty1EndBattleText"] = "\nE sembravi\ncosì carino!",
  ["_Route15Beauty2AfterBattleText"] = "Mi piace tornare\na casa per stare\11con i miei POKéMON!",
  ["_Route15Beauty2BattleText"] = "Curo POKéMON\nperché vivo sola!",
  ["_Route15Beauty2EndBattleText"] = "Non l'ho\nchiiesto io!",
  ["_Route15Biker1AfterBattleText"] = "Si vive una volta\nsola, e io vivo\11da fuorilegge!\12REGOLE del\nTEAM ROCKET!",
  ["_Route15Biker1BattleText"] = "Ehi! Vieni qui!\nGuarda questo!",
  ["_Route15Biker1EndBattleText"] = "Perché\nno?",
  ["_Route15Biker2AfterBattleText"] = "Scherzavo sui\nsoldi!",
  ["_Route15Biker2BattleText"] = "Ascolta, moccioso:\nse perdi contro\11di me, tutti i tuoi\11soldi saranno miei!",
  ["_Route15Biker2EndBattleText"] = "Ma\nè impossibile!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Non puoi cambiare\nil soprannome a\11un POKéMON scambiato.\12Solo l'allenatore\noriginale può farlo!",
  ["_Route15CooltrainerF1BattleText"] = "Fammi provare il\nPOKéMON che\11ho appena scambiato!",
  ["_Route15CooltrainerF1EndBattleText"] = "Non è\nbastato!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Ho paura dei\nMOTOCICLISTI, sono\11brutti e cattivi!",
  ["_Route15CooltrainerF2BattleText"] = "Sembri mansueto!\nCredo di poterti\11battere!",
  ["_Route15CooltrainerF2EndBattleText"] = "No,\nmale male!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Scambio POKéMON\ncon i miei amici!",
  ["_Route15CooltrainerF3BattleText"] = "Che c'è di figo?\nScambiare POKéMON!",
