  ["_Route22Rival1DefeatedText"] = "Ahi!\nChe sfortuna!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Cosa?\nPerché ho due\11POKéMON?\12Dovresti catturarne\nqualcuno in più\11anche tu!",
