 ["_Route24CooltrainerM2AfterBattleText"] = "Mi sono nascosto\nperché mi hanno\11spaventato sul ponte!",
  ["_Route24CooltrainerM2BattleText"] = "Ho visto la tua\nimpresa dall'erba!",
  ["_Route24CooltrainerM2EndBattleText"] = "\nPensavo che non\11mi avresti battuto!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Ho fatto del\nmio meglio!",
  ["_Route24CooltrainerM3BattleText"] = "Sono il 5º!\nTi schiaccerò!",
  ["_Route24CooltrainerM3EndBattleText"] = "\nUau! È stato\11troppo!",
  ["_Route24Youngster1AfterBattleText"] = "Ho fatto del\nmio meglio!",
  ["_Route24Youngster1BattleText"] = "Sono il 3º!\nTi costerà caro!",
  ["_Route24Youngster1EndBattleText"] = "Ehi!\nMi hai distrutto!",
  ["_Route24Youngster2AfterBattleText"] = "Ho fatto del\nmio meglio!",
  ["_Route24Youngster2BattleText"] = "Questo è il\nPONTE DI HUG!\12Batti tutti e 5\ne vinci un premio\11favoloso!\12Credi di farcela?",
  ["_Route24Youngster2EndBattleText"] = "Uau!\nBel match!",
  ["_Route25BillSignText"] = "CASA DEL MARE\nBILL vive qui!",
  ["_Route25CooltrainerF1AfterBattleText"] = "Magari il mio\nragazzo fosse in\11gamba come te!",
  ["_Route25CooltrainerF1BattleText"] = "Ciao! Il mio\nragazzo è un mito!",
  ["_Route25CooltrainerF1EndBattleText"] = "Non ero\nin forma!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Vieni dal M.TE\nMOON? Mi dai un\11CLEFAIRY?",
  ["_Route25CooltrainerF2BattleText"] = "Un mio amico ha\nun POKéMON carino.\11Che invidia!",
  ["_Route25CooltrainerF2EndBattleText"] = "\nIo non sono così\ninvidiosa!",
  ["_Route25CooltrainerMAfterBattleText"] = "Va bene! La mia\nragazza farà il\11tifo per me.",
  ["_Route25CooltrainerMBattleText"] = "Sono un bravo\nragazzo e ho la\11ragazza!",
  ["_Route25CooltrainerMEndBattleText"] = "\nMaledizione...",
  ["_Route25Hiker1AfterBattleText"] = "Aaaaaargh!\nMi ha morso un\11ZUBAT.",
  ["_Route25Hiker1BattleText"] = "Sono appena sceso\ndall M.TE MOON,\11ma sono pronto!",
  ["_Route25Hiker1EndBattleText"] = "\nHai lavorato\nduramente!",
  ["_Route25Hiker2AfterBattleText"] = "Il collezionista\nha molti POKéMON\11rari.",
  ["_Route25Hiker2BattleText"] = "Sto cercando un\ncollezionista di\11POKéMON al capo!",
  ["_Route25Hiker2EndBattleText"] = "\nMi hai battuto!",
  ["_Route25Hiker3AfterBattleText"] = "La strada sotto\nè una scorciatoia\11per CELESTE.",
  ["_Route25Hiker3BattleText"] = "Vai da BILL?\nLottiamo prima!",
  ["_Route25Hiker3EndBattleText"] = "Te la cavi bene.",
  ["_Route25Youngster1AfterBattleText"] = "Ogni POKéMON\nha i suoi punti\11deboli. Meglio\11allenare vari tipi.",
  ["_Route25Youngster1BattleText"] = "Gli allenatori locali\nvengono qui ad\11allenarsi!",
  ["_Route25Youngster1EndBattleText"] = "Te la cavi bene.",
  ["_Route25Youngster2AfterBattleText"] = "Sulla S.S. ANNE\nho visto allenatori\11da tutto il mondo.",
  ["_Route25Youngster2BattleText"] = "Mio padre mi\nha portato a una\11grande festa sulla\11S.S. ANNE a ARANCIO!",
  ["_Route25Youngster2EndBattleText"] = "Non sono\narrabbiato!",
  ["_Route25Youngster3AfterBattleText"] = "Se il tuo POKéMON\nsi confonde o si\11addormenta, cambialo!",
  ["_Route25Youngster3BattleText"] = "Sapevo che avrei\ndovuto lottare\11con te!",
  ["_Route25Youngster3EndBattleText"] = "Sapevo che avrei\nperso!",
  ["_Route2DiglettsCaveSignText"] = "GROTTA DI DIGLETT",
  ["_Route2GateOaksAideFlashExplanationText"] = "FLASH illumina\nanche le grotte\11più buie.",
  ["_Route2GateYoungsterText"] = "Se un POKéMON\nimpara FLASH,\11potrai attraversare\11il TUNNEL ROCA.",
  ["_Route2SignText"] = "PERCORSO 2:\nVIRIDIANOPOLI -\nPLUMEOPOLI",
  ["_Route2TradeHouseScientistText"] = "Un POKéMON esausto\nnon può lottare,\11ma può usare\11mosse come TAGLIO!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Smettila di fissarmi\nse non vuoi\11lottare!",
  ["_Route3CooltrainerF1BattleText"] = "Mi stavi fissando,\nvero?",
  ["_Route3CooltrainerF1EndBattleText"] = "Sei proprio\ncattivo!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Evita le lotte\nnascondendoti tra\11la gente!",
  ["_Route3CooltrainerF2BattleText"] = "Quel tuo sguardo\nera molto\11misterioso!",
 ["_Route3CooltrainerF2EndBattleText"] = "\nSii gentile!",
  ["_Route3CooltrainerF3AfterBattleText"] = "Il PERCORSO 4 è\nsotto il M.TE MOON.",
  ["_Route3CooltrainerF3BattleText"] = "Ehi! Perché\nmi hai toccato?",
  ["_Route3CooltrainerF3EndBattleText"] = "\nTutto qui?",
  ["_Route3SignText"] = "PERCORSO 3:\nVERSO IL M.TE MOON",
  ["_Route3Text1"] = "Uff!... Meglio\nche riposi.\n(Sussulto)...\nQuel tunnel per\nCELESTE è faticoso!",
  ["_Route3Youngster1AfterBattleText"] = "Ci sono altri\ntipi di POKéMON\noltre a quelli\11del bosco!",
  ["_Route3Youngster1BattleText"] = "Ci siamo visti nel\nBOSCO VERDE!",
  ["_Route3Youngster1EndBattleText"] = "Hai vinto di\nnuovo!",
  ["_Route3Youngster2AfterBattleText"] = "Deponiti i POKéMON\nnel PC? Ogni BOX\npuò contenere\1120 POKéMON!",
  ["_Route3Youngster2BattleText"] = "Ciao! Mi piacciono\ni pantaloncini!\nSono così comodi!",
  ["_Route3Youngster2EndBattleText"] = "Non ci posso\ncredere!",
  ["_Route3Youngster3AfterBattleText"] = "Se un BOX di\nPOKéMON è pieno,\npassa a un altro\11BOX!",
  ["_Route3Youngster3BattleText"] = "Sei un allenatore?\nAllora lottiamo!",
  ["_Route3Youngster3EndBattleText"] = "Con POKéMON\nnuovi ti avrei\11battuto!",
  ["_Route3Youngster4AfterBattleText"] = "Indosso i pantaloncini\ninverno e estate.",
  ["_Route3Youngster4BattleText"] = "Ehi! Non hai i\npantaloncini!",
  ["_Route3Youngster4EndBattleText"] = "\nHo perso! Ho perso!",
  ["_Route3Youngster5AfterBattleText"] = "I POKéMON allenati\nsono più forti di\11quelli selvatici!",
  ["_Route3Youngster5BattleText"] = "Puoi lottare\ncontro i miei nuovi\11POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "Sono\nfinito!",
  ["_Route4CooltrainerF1Text"] = "Ahi! Sono inciampata\nsu un POKéMON di\11roccia, GEODUDE!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Forse non ci sono\naltri funghi qui!\nCredo di averli\11presi tutti.",
  ["_Route4CooltrainerF2BattleText"] = "Sono venuta a\nprendere i miei\11funghi POKéMON!",
  ["_Route4CooltrainerF2EndBattleText"] = "\nOh! Il mio povero\nfungo POKéMON!",
  ["_Route4MtMoonSignText"] = "M.TE MOON:\nIngresso tunnel",
  ["_Route4SignText"] = "PERCORSO 4:\nM.TE MOON -\nCELESTE",
  ["_Route5UndergroundPathSignText"] = "GALLERIA SOTTERRANEA:\nCELESTE - ARANCIO",
  ["_Route6CooltrainerAfterBattleText"] = "(Bisbiglio)...\n(Bisbiglio)...",
  ["_Route6CooltrainerF1BattleText"] = "Scusa! Questa\nconversazione\11è privata!",
  ["_Route6CooltrainerF1EndBattleText"] = "\nOdio perdere!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Voglio diventare\npiù forte! Qual è\11il tuo segreto?",
  ["_Route6CooltrainerF2BattleText"] = "Io? D'accordo.\nGiochiamo!",
  ["_Route6CooltrainerF2EndBattleText"] = "Non ha\nfunzionato!",
  ["_Route6CooltrainerM1BattleText"] = "Chi c'è?\nSmettila di\11spiarci!",
  ["_Route6CooltrainerM1EndBattleText"] = "\nNon riesco proprio\na vincere!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Dovrei portare\npiù POKéMON\11per protezione.",
  ["_Route6CooltrainerM2BattleText"] = "Cosa? Vuoi\nparlare con me?",
  ["_Route6CooltrainerM2EndBattleText"] = "Non ho iniziato\nio!",
  ["_Route6UndergroundPathSignText"] = "GALLERIA SOTTERRANEA:\nCELESTE - ARANCIO",
  ["_Route6Youngster1AfterBattleText"] = "Mi piacciono gli\ninsetti. Tornerò\11al BOSCO VERDE.",
  ["_Route6Youngster1BattleText"] = "Non ci sono molti\ninsetti qui.",
  ["_Route6Youngster1EndBattleText"] = "No!\nScherzi?",
  ["_Route6Youngster2AfterBattleText"] = "È debole il mio\nPOKéMON o sono\11io scarso?",
  ["_Route6Youngster2BattleText"] = "Non ti avevo mai\nvisto! Sei forte?",
  ["_Route6Youngster2EndBattleText"] = "Sei troppo\nforte!",
  ["_Route7UndergroundPathSignText"] = "GALLERIA SOTTERRANEA:\nAZZURROPOLI -\nPUEBLO LAVANDA",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quando i POKéMON\ncrescono diventano\11brutti! Non mi\11piacciono quando\11evolvono!",
  ["_Route8CooltrainerF1BattleText"] = "Mi piacciono i\nNIDORAN, perciò\11li colleziono!",
  ["_Route8CooltrainerF1EndBattleText"] = "Ma,\nperché?",
 ["_Route8CooltrainerF2AfterBattleText"] = "Credo che anche\nPIDGEY e RATTATA\11siano carinissimi!",
  ["_Route8CooltrainerF2BattleText"] = "MEOWTH è carinissimo,\nmiaola, miaola!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miao!",
  ["_Route8CooltrainerF3AfterBattleText"] = "La guardia di\nZAFFERANOPOLI non\11ci fa passare.\11È cattivissima!",
  ["_Route8CooltrainerF3BattleText"] = "Dobbiamo avere\nuna faccia da\11babbei!",
  ["_Route8CooltrainerF3EndBattleText"] = "Guarda cosa\nhai fatto!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Dicono che CLEFAIRY\nsi trasformi se\11esposto a una\11PIETRALUNARE.",
  ["_Route8CooltrainerF4BattleText"] = "Quale POKéMON è\ncarino, rotondo\11e soffice?",
  ["_Route8CooltrainerF4EndBattleText"] = "Alt!\nNon essere così cattivo\11con i miei CLEFAIRY!",
  ["_Route8Gambler1AfterBattleText"] = "Oggi non è la mia\ngiornata fortunata!",
  ["_Route8Gambler1BattleText"] = "Benissimo!\nTiriamo i dadi!",
  ["_Route8Gambler1EndBattleText"] = "\nMaledizione!\nMi sono fermato prima!",
  ["_Route8Gambler2AfterBattleText"] = "Il gioco e i POKéMON\nsono come le ciliegie,\11uno tira l'altro!",
  ["_Route8Gambler2BattleText"] = "Sono un giocatore\nerrante!",
  ["_Route8Gambler2EndBattleText"] = "Ho perso\nil montepremi!",
  ["_Route8SuperNerd1AfterBattleText"] = "Me la cavo meglio\na scuola!",
  ["_Route8SuperNerd1BattleText"] = "Sembri bravo coi\nPOKéMON, ma...\11come vai in chimica?",
  ["_Route8SuperNerd1EndBattleText"] = "Ah!\nFusione nucleare!",
  ["_Route8SuperNerd2AfterBattleText"] = "Usa prima GRIMER\ne poi... e poi...",
  ["_Route8SuperNerd2BattleText"] = "Ci vuole una\nbuona strategia!",
  ["_Route8SuperNerd2EndBattleText"] = "Non ha\nsenso!",
  ["_Route8SuperNerd3AfterBattleText"] = "Le porte di\nZAFFERANOPOLI ci\11tengono bloccati.",
  ["_Route8SuperNerd3BattleText"] = "Mi piace la scuola\ne i POKéMON!",
  ["_Route8SuperNerd3EndBattleText"] = "\nPreferisco\nla scuola.",
  ["_Route8UndergroundSignText"] = "GALLERIA SOTTERRANEA:\nAZZURROPOLI -\nPUEBLO LAVANDA",
  ["_Route9CooltrainerF1AfterBattleText"] = "Ti serve luce\nper attraversare\11quel tunnel buio.",
  ["_Route9CooltrainerF1BattleText"] = "Hai dei POKéMON!\nIn guardia!",
  ["_Route9CooltrainerF1EndBattleText"] = "Mi hai\ndeluso!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Sembri molto\ncapace! Buona fortuna!",
  ["_Route9CooltrainerF2BattleText"] = "Trattami con\nrispetto!",
  ["_Route9CooltrainerF2EndBattleText"] = "\nSei troppo forte!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Continua a camminare!",
  ["_Route9CooltrainerM1BattleText"] = "Chi si ė azzardato\na portare in giro\11quei POKéMON così\11belli?",
  ["_Route9CooltrainerM1EndBattleText"] = "\nÈ finita!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Vai anche tu\nal TUNNEL ROCA?",
  ["_Route9CooltrainerM2BattleText"] = "Prenderò il TUNNEL\nROCA per andare a\11PUEBLO LAVANDA!",
  ["_Route9CooltrainerM2EndBattleText"] = "\nSono una frana!\nUffa!",
  ["_Route9Hiker1AfterBattleText"] = "Devi essere molto\ncoraggioso per\11sfidarmi!",
  ["_Route9Hiker1BattleText"] = "Ah ah! Che bello!\nMi annoiavo!",
  ["_Route9Hiker1EndBattleText"] = "\nNon fermarti,\ncontinua così!\12Aspetta. Non ho\npiù POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "Ah ah! I ragazzi\ndevono essere tosti!",
  ["_Route9Hiker2BattleText"] = "Ah ah!\nNon mi sembri\11molto duro!",
  ["_Route9Hiker2EndBattleText"] = "Cos'è\nquesto?",
  ["_Route9Hiker3AfterBattleText"] = "Ah ah!\nI più forti ridono\11sempre per ultimi!",
  ["_Route9Hiker3BattleText"] = "Ah ah ah!\nForza, moccioso!",
  ["_Route9Hiker3EndBattleText"] = "\nAh ah ah!\nMi hai battuto!",
  ["_Route9SignText"] = "PERCORSO 9:\nCELESTE - TUNNEL ROCA",
  ["_Route9Youngster1AfterBattleText"] = "Devo allevare\nqualcosa di diverso\11dagli insetti per\11diventare più forte...",
  ["_Route9Youngster1BattleText"] = "Mi alzo presto\ntutte le mattine\11per curare i\11miei POKéMON-baco!",
  ["_Route9Youngster1EndBattleText"] = "COSA?\nChe gran perdita\11di tempo!",
 ["_Route9Youngster2AfterBattleText"] = "Non ti piacciono i\nPOKéMON insetto?\11Contagiami pure!",
  ["_Route9Youngster2BattleText"] = "Avanti, il mio\nsuper POKéMON\11insetto!",
  ["_Route9Youngster2EndBattleText"] = "I miei\ninsetti...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Hai fatto del male\nai miei poveri\11POKéMON!\12Prendo e li porto\na far curare in\11un CENTRO POKéMON!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Ho raccolto questi\nPOKéMON in tutto\11il mondo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Oh no!\nHo viaggiato per\11tutto il mondo\11solo per loro!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Dovresti comportarti\nbene con gli amici!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Viaggio da solo!\nI miei POKéMON\11sono i miei unici\11amici!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Oh!\nI miei amici!",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Vorrei che mi\nlasciassi in pace!\12Fuori di qui!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Ehi tu, moccioso!\nCome ti permetti\11di entrare qui?",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Ehi!\nSei un bambino\11molto maleducato!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Ssh! Sono un agente\ndi POLIZIA!\12Sulle tracce del\nTEAM ROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "Cameriere, vorrei\nuna fetta di\11torta di ciliegie!",
  ["_SSAnne1FRoomsGirl2Text"] = "Facciamo una\ncrociera intorno\11al mondo!",
  ["_SSAnne1FRoomsLittleGirlText"] = "Viaggio sempre\ncon WIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Le navi da crociera\nsono così eleganti\11e accoglienti!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: Wig\nTuuuf, Tuuuf!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Facciamo amicizia?\nCosì potremo\11scambiarci POKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Mi piacciono i\nPOKéMON! E a te?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Uau!\nSei fantastico!",
  ["_SSAnne1FSailorText"] = "I passeggeri si\nstanno spazientendo!\12Quelli più annoiati\npotrebbero sfidarti!",
  ["_SSAnne1FWaiterText"] = "Bonjour! Sono\nil cameriere di\11questa nave!\12Piacere di servirti\nin tutto ciò che\11vuoi! Sembri il\11tipo forte e silenzioso!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Dicevano\nche c'era un\11maestro di TAGLIO\11a bordo.\12Ma era solo un\nvecchio stordito!\12Però la tecnica\ndi TAGLIO è molto\11utile! Vallo a\11trovare! A presto!",
  ["_SSAnne2FRivalDefeatedText"] = "Acciderboli!\nSembra che tu abbia\11allenato bene i\11tuoi POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}:\nBonjour {PLAYER}!\12Sapevo che ti\narei trovato qui!\12{PLAYER}, sei\nstato davvero\11invitato?\12Come va il POKéDEX?\nHo già 40 POKéMON,\11moccioso!\12Sono dappertutto!\nAddentrati nell'erba\11alta!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}!\nHai il mal di mare?\12Dovresti rimetterti\nin sesto, amico!",
  ["_SSAnne2FRoomsBeautyText"] = "Dicono che molta\ngente soffra il\11mal di mare!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Il CAPITANO sembrava\nmolto pallido e\11provato!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Oh! Adoro i tuoi\nforti POKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Non ti avevo mai\nvisto alla festa.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Ehi!\nNon agitarti!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "Una festa?\nLa festa sulla\11nave sarà finita.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Guarda cosa\nho pescato!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "\nSono finito!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "Quindici anni fa\nle avrei vinte tutte!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Gareggiare con\ni giovani mi\11mantiene giovane!",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Bel combattimento!\nMi sento di nuovo\11giovane!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Preferisco i\nPOKéMON forti\11e rari!",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Cosa preferisci,\nun POKéMON forte\11o uno raro?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Devo\ncomplimentarmi!",
  ["_SSAnne2FRoomsGentleman3Text"] = "In tutti i miei\nviaggi non avevo\11mai visto un POKéMON\11dormire così tanto!\12Era fatto così...",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ah sì! Ho visto\ndei POKéMON\nportare gente\11attraverso l'acqua!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Sei stato alla\nZONA SAFARI a\11FUCSIAPOLI?\12C'erano tanti\ntipi rari di\11POKéMON!",
  ["_SSAnne2FRoomsGrampsText"] = "I POKéMON\npossono TAGLIARE\11piccoli arbusti.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Io e mio padre\ncrediamo che la\11ZONA SAFARI sia\11fantastica!",
  ["_SSAnne2FWaiterText"] = "Questa nave di\nlusso è per gli\11allenatori!\12Festeggiamo in\nogni porto per\11gli allenatori!",
  ["_SSAnne3FSailorText"] = "Il nostro CAPITANO\nè un maestro di\11scherma!\12Insegna perfino\nai POKéMON la\11tecnica di TAGLIO!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Volevo fare anche\nte mio aiutante!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Ehi forestiero!\nFermati a parlare!\12Tutti i miei POKéMON\nvengono dal mare!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "\nMaledizione!\nMi è scappato!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: Cho!\nChoke Cho!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Ahimè! Vuoi\ndiventare marinaio?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Sai cosa dicono\nsulle risse tra\11marinai!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "\nHai lottato alla\ngrande, compagno!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Hai visto il GURU\ndei PESCATORI a\11ARANCIO?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "È in gioco la mia\nfama di marinaio!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "\nIl tuo spirito\nmi ha affondato!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Peschiamo tutti\ni nostri POKéMON\11in alto mare!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Anche noi marinai\nabbiamo POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "Te la cavi\nbene!",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "I POKéMON marini\nvivono nelle profondità.\11Ti servirà una\11CANNA!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Mi piacciono i\ngiovani attivi\11come te!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Argh!\nHo perso!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "A volte qualche\nmedusa finisce\11sulla nave.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Se perdi, camminerai\nsull'asse, amico!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nSconfitto da un\11ragazzino!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Il mio amico,\nMACHOKE, è fortissimo!\12Ha così tanta\nFORZA da spostare\11anche massi enormi!",
  ["_SSAnneBowCooltrainerMText"] = "Uff! Mi sento\nmale...\nSono uscito a\11prendere aria.",
  ["_SSAnneBowSailor1Text"] = "Pulire i ponti\nè un lavoro duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Quanti tipi di\nPOKéMON pensi\11che esistano?",
  ["_SSAnneBowSailor2BattleText"] = "Ehi, amico!\nBalliamo un jig!",
  ["_SSAnneBowSailor2EndBattleText"] = "Sei\nimpressionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Papà diceva che\nci sono 100 tipi\11di POKéMON, ma\11secondo me ce\11sono di più.",
  ["_SSAnneBowSailor3BattleText"] = "Ahimè, marinaio!\nHai il mal di mare?",
  ["_SSAnneBowSailor3EndBattleText"] = "Non sono stato\nattento!",
  ["_SSAnneBowSuperNerdText"] = "La festa è finita!\nLa nave salperà\11presto!",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Oh no! Non hai\nspazio per questo!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITANO: Uff!\nGrazie! Mi sento\11molto meglio...\12Vuoi vedere la mia\ntecnica di TAGLIO?\11Te la mostrei se\11non fossi così\11stordito. Lo so!\12Prendi questo!\nInsegnalo al tuo\11POKéMON e taglierà\11in un attimo!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITANO: Bene!\nOra che non ho\11più il mal di mare,\11dovremmo partire!",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITANO: Bleah!\nSto malissimo.\nIl mal di mare...\12{PLAYER} massaggia\nil CAPITANO!\n(Grattino)...\n(Grattino)...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Come combattere il\nmal di mare...\nIl CAPITANO lo\11sta leggendo!",
  ["_SSAnneCaptainsRoomTrashText"] = "Che schifo!\nNon avrei dovuto\11guardare!",
  ["_SSAnneKitchenCook1Text"] = "Ehi, moccioso!\nSiamo occupati!\nFuori di qui!",
  ["_SSAnneKitchenCook2Text"] = "Ho visto una strana\npalla nella spazzatura.",
  ["_SSAnneKitchenCook3Text"] = "Sono così occupato\nche mi gira la\11testa!",
  ["_SSAnneKitchenCook4Text"] = "Perché?\nPerché proprio io?\12Passo tutto il\ngiorno a pelare\11patate!",
  ["_SSAnneKitchenCook5Text"] = "Hai sentito parlare\ndi SNORLAX?\12Mangia e dorme\nininterrottamente!",
  ["_SSAnneKitchenCook6Text"] = "Sniff... sniff...\nPelato solo cipolle...\11Sniff...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Ehm! Sono lo\nCHEF per un motivo!\12Il menu è:",
  ["_SSTicketNoRoomText"] = "Hai troppe cose,\nragazzo.",
  ["_SSTicketReceivedText"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "Il {RAM:wEnemyMonNick}\nselvaggio è\11arrabbiato!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: Dov'è\nandato il mio\11amico ERIC?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Sto catturando\nPOKéMON da portare\11a casa come regali!",
  ["_SafariZoneCenterRestHouseSignText"] = "CASA DI RIPOSO",
  ["_SafariZoneCenterTrainerTipsSignText"] = "CONSIGLI UTILI\nPremi START per\nverificare il tempo\11rimasto!",
  ["_SafariZoneEastRestHouseRockerText"] = "Ho catturato un\nCHANSEY!\nNe è valsa la pena!",
  ["_SafariZoneEastRestHouseScientistText"] = "Quanti ne hai\ncatturati? Io sono\11distrutto dal lavoro!",
  ["_SafariZoneEastRestHouseSignText"] = "CASA DI RIPOSO",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Uff! Sono distrutto\nper tutto il divertimento!",
  ["_SafariZoneEastSignText"] = "ZONA CENTRO-NORD:\nAREA 2",
  ["_SafariZoneEastTrainerTipsText"] = "CONSIGLI UTILI\nIl tempo residuo\11diminuisce solo\11mentre cammini!",
  ["_SafariZoneEatingText"] = "Il {RAM:wEnemyMonNick}\nselvaggio sta\11mangiando!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\nTi avviseremo\nquando finiranno\11le SAFARI BALL o\11il tempo!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "È stata una buona\ncaccia? Torna\11quando vuoi!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Buona fortuna!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Te ne vai già?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ops! Non hai\nabbastanza soldi!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "Ottimo! Torna\nquando vuoi!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Restituisci le\nSAFARI BALL che\11ti sono avanzate.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Benvenuti nella\nZONA SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Sono ¥500,\nper favore!\nQui si usano\11solo POKé BALL\11speciali.\n{PLAYER} ottiene\1130 SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Per soli ¥500\npuoi catturare\11tutti i POKéMON\11che vuoi nel parco!\12Vuoi partecipare\nalla caccia?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Ciao! È la tua\nprima volta qui?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "La ZONA SAFARI ha\n4 aree.\nOgni area ha\11diversi POKéMON.\12Usa le SAFARI BALL\nper prenderli!\nSe finisci il tempo\11o le SAFARI BALL,\11la gara finisce!\12Prima di andare,\napri un nuovo BOX\11per avere spazio!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Ah, sei un\nabituè qui!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Il mio EEVEE si\nè evoluto in\11FLAREON!\nMa quello di un\11mio amico in un\11VAPOREON! Perché?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Vai nell'area più\nprofonda del SAFARI.\11Vincerai un premio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Puoi tenere qualsiasi\nstrumento trovi\11qui.\nMa perderai tempo\11se cerchi di prenderli\11tutti insieme!",
  ["_SafariZoneNorthRestHouseSignText"] = "CASA DI RIPOSO",
  ["_SafariZoneNorthSignText"] = "AREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "CONSIGLI UTILI\nLa CASA SEGRETA\nè sempre dritta\11davanti a te!",
  ["_SafariZoneNorthTrainerTips2Text"] = "CONSIGLI UTILI\nI POKéMON si\nattirano nell'erba\11alta camminandoci\11dentro a zig-zag!",
  ["_SafariZoneNorthTrainerTips3Text"] = "CONSIGLI UTILI\nTrova la CASA SEGRETA\nper vincere una MN!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "La MN03 è SURF!\nUn POKéMON\11ti porterà sull'acqua!\12E questa MN può\nessere usata infinite\11volte! Che colpo\11di fortuna! Sei il\11vincitore del premio!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Non hai spazio\nper questo premio\11favoloso!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Finalmente!\nSei il primo ad\11arrivare alla\11CASA SEGRETA!\12Temevo che nessuno\navesse vinto.\nComplimenti!\11Sei il vincitore!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVVISO\nTrova i DIENTI D'ORO\11smarriti dal GUARDIANO\nSAFARI.\nÈ prevista una ricompensa!\11Contatta il GUARDIANO.",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Usare le ESCHE\nrende i POKéMON\11più facili da\11catturare.",
  ["_SafariZoneWestRestHouseScientistText"] = "Lanciare SASSI ai\nPOKéMON li fa\11fuggire, ma saranno\11più facili da\11prendere.",
  ["_SafariZoneWestRestHouseSignText"] = "CASA DI RIPOSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Ho camminato tanto,\nma non ho visto\11i POKéMON che\11volevo.",
  ["_SafariZoneWestSignText"] = "ZONA 3\nEST: AREA CENTRALE",
  ["_SafariZoneWestTrainerTipsText"] = "CONSIGLI UTILI\nOperazione Esplorazione\nZona!\nLa caccia alla\11CASA SEGRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO KARATE",
  ["_SaffronCityGentlemanText"] = "Sono arrivato qui\nin PIDGEOT quando\11ho saputo della SILPH.\12È già finita?\nMi sono perso\11tutta l'azione.",
  ["_SaffronCityGymSignText"] = "CAPOPALESTRA di\nZAFFERANOPOLI:\11SABRINA\nMaestra dei POKéMON\11psichici!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DEL\nSIG. PSICHICO",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: Pid pid!",
  ["_SaffronCityPokecenterGuyText1"] = "Sarebbe bello se\ni Superquattro\11venissero a dar\11le sode al TEAM ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "Il TEAM ROCKET\nè andato via! Ora\11possiamo uscire\11al sicuro! Evviva!",
  ["_SaffronCityRockerText"] = "Ho visto il CAPO\nROCKET scappare\11dall'edificio SILPH.",
  ["_SaffronCityRocket1Text"] = "Che vuoi?\nSparisci!",
  ["_SaffronCityRocket2Text"] = "Il CAPO dice che\ninvaderà questa\11città!",
  ["_SaffronCityRocket3Text"] = "Fuori dai piedi!",
  ["_SaffronCityRocket4Text"] = "ZAFFERANOPOLI\nè del TEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "Essere cattivo\nmi fa sentire vivo!",
 ["_SaffronCityRocket6Text"] = "Ahi! Attento a\ndove cammini!",
  ["_SaffronCityRocket7Text"] = "Con la SILPH sotto\ncontrollo, possiamo\11sfruttare i POKéMON\11di tutto il mondo!",
  ["_SaffronCityRocket8Text"] = "Sono la guardia\ndi sicurezza!\nNon faccio entrare\11ragazzi sospetti!",
  ["_SaffronCityRocket9Text"] = "...\n(Russamento)...\nAh! Sta facendo\11un pisolino!",
  ["_SaffronCityScientistText"] = "Hai sconfitto tu\nda solo il TEAM\11ROCKET? Incredibile!",
  ["_SaffronCitySignText"] = "ZAFFERANOPOLI\nLa splendente e\11dorata terra del\11commercio.",
  ["_SaffronCitySilphCoLatestProductSignText"] = "L'ultima novità\ndella SILPH!\nLanciata per essere\11decisiva...",
  ["_SaffronCitySilphCoSignText"] = "EDIFICIO UFFICI\ndella SILPH S.p.A.",
  ["_SaffronCitySilphWorkerFText"] = "La gente può\nfinalmente tornare\11a ZAFFERANOPOLI.",
  ["_SaffronCitySilphWorkerMText"] = "Il TEAM ROCKET\nè andato via!\12Ora possiamo uscire\ndi nuovo!",
  ["_SaffronCityTrainerTips1Text"] = "CONSIGLI UTILI\nCURAPOZIONE cura\ni problemi come\11il sonno e le ustioni.\12Costa un po' di più,\nma ne vale la pena.",
  ["_SaffronCityTrainerTips2Text"] = "CONSIGLI UTILI\nLa nuova SÚPER\nBALL offre una\11maggiore velocità\11di cattura.\12Provala con\ni POKéMON più\11difficili da prendere.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Sono di guardia.\nUff! Che sete!\12Aspetta. La strada\nè chiusa.",
  ["_SaffronGateGuardImParchedText"] = "Uff, ragazzo!\nHo una sete...\n...\nMi dai questa bibita?\11Grazie, giovanotto!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Ehi! Grazie per\nle bibite!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\n...\nGlu glu...\n...\n(Sorso)...\nSe vuoi andare a\11ZAFFERANOPOLI...\n...\nPuoi passare...\nCondividerò questo\11con gli altri guardie!",
  ["_SaffronGymChanneler1AfterBattleText"] = "In una lotta alla\npari, vince chi ha\11più forza di volontà!\12Se vuoi battere\nSABRINA, pensa\11solo a vincere!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA è più\ngiovane di me,\11ma la rispetto!",
  ["_SaffronGymChanneler1EndBattleText"] = "\nChe errore!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Devo insegnare\ntecniche migliori\11ai miei POKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "I POKéMON finiscono\nper assomigliare\11ai loro allenatori.\12I tuoi POKéMON\nsembrano forti!",
  ["_SaffronGymChanneler2EndBattleText"] = "\nLo sapevo!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Sapevo che sarebbe\nandata a finire così.",
  ["_SaffronGymChanneler3BattleText"] = "Tu ed io!\nI nostri POKéMON\11devono lottare.",
  ["_SaffronGymChanneler3EndBattleText"] = "\nAlla fine ho perso!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Potere mentale?\nSe ce l'avessi,\nsarei ricco alle\11slot machine!",
  ["_SaffronGymGuideChampInMakingText"] = "Ehi, futuro\ncampione!\nI POKéMON di SABRINA\11usano la forza\11mentale, non i muscoli!\12I POKéMON lottatori\nsono deboli contro\11quelli psichici!\12Vengono stesi prima\ndi poter reagire!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "Con la MEDAGLIA\nPANTANO, tutti i\11POKéMON fino al\11livello 70 ti ubbidiranno!\12I POKéMON più forti\nignoreranno i tuoi\11ordini in battaglia!\12Non esagerare con\nil loro allenamento!\12Prendi questa MT!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Tutti hanno poteri\nmentali, ma la\11gente li ignora!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Sono impressionata!\nAccetto la sconfitta.\12Ammetto di non\naver tenuto testa\11e di aver perso!\12Hai vinto la\nMEDAGLIA PANTANO!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} ottiene\nla MT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "La tua borsa\nè piena di altri\11strumenti!",
  ["_SaffronGymSabrinaText"] = "Ho avuto una visione\ndel tuo arrivo!\nHo poteri psichici\11da quando ero bambina!\12Prima ho imparato\na piegare i cucchiai\11con la mente.\12Odio lottare, ma\nse vuoi posso mostrarti\11i miei poteri!",
  ["_SaffronGymYoungster1AfterBattleText"] = "I POKéMON psichici\ntemono solo gli\11insetti e gli spiriti!",
  ["_SaffronGymYoungster1BattleText"] = "Il nostro potere\nnascosto ti spaventa?",
  ["_SaffronGymYoungster1EndBattleText"] = "Non l'avrei\nmai detto!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA ha battuto\nil MAESTRO DI KARATE\11della porta accanto!",
  ["_SaffronGymYoungster2BattleText"] = "Sai che la tua\nsola forza non\11basta!",
  ["_SaffronGymYoungster2EndBattleText"] = "Non ci posso\ncredere!",
  ["_SaffronGymYoungster3AfterBattleText"] = "A ZAFFERANOPOLI\nc'erano 2 PALESTRE\11POKéMON.\nIl DOJO KARATE\11qui accanto ha perso\11lo status di palestra\11quando li abbiamo asfaltati!",
  ["_SaffronGymYoungster3BattleText"] = "SABRINA è giovane,\nma è la nostra\11CAPOPALESTRA!\nNon arriverai a lei\11facilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "Non sono riuscito\na concentrarmi!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Hai ragione!\nHo usato la telepatia\11per leggerti la mente!",
  ["_SaffronGymYoungster4BattleText"] = "La PALESTRA di\nZAFFERANOPOLI è famosa\11per i suoi medium!\12Vuoi vedere SABRINA!\nLo so!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgg!",
  ["_SaffronMartCooltrainerFText"] = "REVIVERE costa\ncaro, ma rianima i\11POKéMON esausti!",
  ["_SaffronMartSuperNerdText"] = "REPELL MAX dura\npiù del SÚPER\nREPELL nel tenere\11lontani i POKéMON\11più deboli!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Grazie per aver\nscritto. A presto!\nEhi, non guardare\11la mia lettera!",
  ["_SaffronPidgeyHousePaperText"] = "Ho ricevuto PP MAX\ncome regalo.\nServe ad aumentare\11i PP delle mosse!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: Pid pid!",
 ["_SaffronPidgeyHouseYoungsterText"] = "La COPIONA è\ncarina! Le darò\11una POKé BAMBOLA!",
  ["_SaffronPokecenterBeautyText"] = "La velocità di\ncrescita dei\11POKéMON varia\11da specie a specie.",
  ["_SaffronPokecenterGentlemanText"] = "SILPH S.A. è molto\nfamosa. Per questo\11il TEAM ROCKET\11ci ha messo gli\11occhi sopra!",
  ["_SandshrewDexEntry"] = "Si nasconde sottoterra,\nin zone aride e\12lontane dall'acqua.\nEsce solo per cacciare.",
  ["_SandslashDexEntry"] = "In pericolo, si\narrotola a palla\nspinosa. Così può\12rotolare per attaccare\no fuggire.",
  ["_SaveOptionText"] = "Nel MENU trovi\nl'opzione SALVA.",
  ["_SavingEnergyText"] = "{USER}\naccumula energia!",
  ["_ScaredText"] = "{RAM:wBattleMonNick}\nè così spaventato\11da non potersi muovere!",
  ["_ScytherDexEntry"] = "Con agilità e velocità\nninja, può creare\nla illusione che\12ce ne siano molti.",
  ["_SeadraDexEntry"] = "Nuota all'indietro\nmuovendo rapidamente\nle pinne pettorali\12e la robusta coda.",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Ar Tic!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "I MASSI possono\ndeviare il flusso\11dell'acqua!",
  ["_SeafoamIslandsB4FDangerSignText"] = "PERICOLO!\nRapide!",
  ["_SeakingDexEntry"] = "In autunno, durante\nla riproduzione,\nsi vedono risalire\12fiumi e torrenti\ncon energia.",
  ["_SeelDexEntry"] = "Il corno sulla testa\nè durissimo.\nLo usa spesso per\12rompere il ghiaccio.",
  ["_SentToBoxText"] = "Non hai spazio\nper altri POKéMON!\12{RAM:wBoxMonNicks}\nè stato spedito\11nel BOX {RAM:wStringBuffer}\11al PC!",
  ["_ShallWeHealYourPokemonText"] = "Vuoi che curiamo\ni tuoi POKéMON?",
  ["_ShellderDexEntry"] = "Il guscio respinge\nogni tipo di attacco.\nÈ vulnerabile solo\12quando si apre.",
  ["_ShroudedInMistText"] = "{USER}\nè avvolto dalla nebbia!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Grrr!\nHo perso di nuovo!?",
  ["_SilphCo10FPorygonText"] = "C'è un POKéMON\nnel monitor!",
  ["_SilphCo10FRocketAfterBattleText"] = "Ben giocato,\nma la sala riunioni\11è un piano sopra!",
  ["_SilphCo10FRocketBattleText"] = "Benvenuto al\n9º piano!\nChe piacere averti\11qui!",
  ["_SilphCo10FRocketEndBattleText"] = "Sono\nstordito!",
  ["_SilphCo10FScientistAfterBattleText"] = "Contento di avermi\nbattuto?\nTorna a casa!",
  ["_SilphCo10FScientistBattleText"] = "Basta con le\nsciocchezze!",
  ["_SilphCo10FScientistEndBattleText"] = "Non ho più\ncontinuazioni!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Uaa!\nHo paura!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Per favore, non dire\na nessuno che ho\11pianto!",
  ["_SilphCo11FBeautyText"] = "SEGRETARIA:\nGrazie per averci\11salvato!\nAmmiriamo il tuo coraggio.",
  ["_SilphCo11FGiovanniText"] = "Ciao {PLAYER}!\nCi risiamo!\nIl PRESIDENTE ed\11io stiamo discutendo\11di cose importanti!\12Non impicciarti\nnegli affari dei\11grandi!\nO subirai la mia ira!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Che peccato!\nHai mandato all'aria\11i nostri piani\11con la SILPH!\12Ma il TEAM ROCKET\nnon cadrà mai!\12{PLAYER}, ricordati\nche tutti i POKéMON\11appartengono al\11TEAM ROCKET!\12Ora devo andare,\nma tornerò!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Cosa?\nVuoi vedere il CAPO?",
  ["_SilphCo11FRocket1BattleText"] = "Alt!\nNon muoverti!",
  ["_SilphCo11FRocket1EndBattleText"] = "No...\nPer favore!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Attento, i POKéMON\ndel CAPO sono\11terribili!",
  ["_SilphCo11FRocket2BattleText"] = "Fermati! Hai\nun appuntamento\11col CAPO?",
  ["_SilphCo11FRocket2EndBattleText"] = "Ahi!\nAtterrato!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE: Non\npuoi comprarla\11da nessuna parte!\nÈ il nostro prototipo\11segreto della\11MASTER BALL!\12Cattura qualsiasi\nPOKéMON!\nMa è meglio non\11farne parola con nessuno.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Non hai spazio\nper questo.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE:\nGrazie per aver\11salvato la SILPH!\nNon dimenticherò\11il tuo aiuto in\11questo momento buio!\12Voglio ringraziarti\nin qualche modo!\nEssendo ricco,\11posso darti tutto!\12Prendi questo,\nforse ti interessa!",
  ["_SilphCo1FLinkReceptionistText"] = "Benvenuto!\nIl PRESIDENTE è\11nella sala riunioni\11al 10º piano!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Le piastrelle a\nrombo sono teletrasporti!\12Sono sistemi di\ntrasporto ad alta\11tecnologia!",
  ["_SilphCo2FRocket1BattleText"] = "Qui i bambini\nnon possono entrare!",
  ["_SilphCo2FRocket1EndBattleText"] = "\nMolto forte!",
  ["_SilphCo2FRocket2AfterBattleText"] = "La SILPH S.p.A.\nsi sta fondendo col\11TEAM ROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "Ehi tu, ragazzino!\nChe ci fai qui?",
  ["_SilphCo2FRocket2EndBattleText"] = "Ho fatto\nun pasticcio!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Lavoro per la\nSILPH S.p.A. e per\11il TEAM ROCKET!",
 ["_SilphCo2FScientist1BattleText"] = "Aiuto! Sono un\ndipendente della\11SILPH S.p.A.!",
  ["_SilphCo2FScientist1EndBattleText"] = "\nCome facevi a\nsapere che ero\11un ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Riuscirai a uscire\nda questo labirinto?",
  ["_SilphCo2FScientist2BattleText"] = "Sei in una zona\nproibita!\nTorna a casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "Sei davvero\nin gamba!",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "La MT36 contiene\nAUTODISTRUZIONE!\12È potentissima,\nma il POKéMON\11che la usa si\11esaurisce molto!\11Fai attenzione!",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Non hai spazio\nper questo!",
  ["_SilphCo3FRocketAfterBattleText"] = "Un indizio? Per\naprire le porte\11usa una TESSERAMAGNES?",
  ["_SilphCo3FRocketBattleText"] = "Ragazzino, non\nci dare altri fastidi!",
  ["_SilphCo3FRocketEndBattleText"] = "\nMi arrendo!",
  ["_SilphCo3FScientistAfterBattleText"] = "Mh...\nIl TEAM ROCKET mi\11ha promesso che,\11se li aiutavo,\11mi avrebbero fatto\11studiare i POKéMON!",
  ["_SilphCo3FScientistBattleText"] = "Sostengo molto più\nil TEAM ROCKET\11che la SILPH S.p.A.!",
  ["_SilphCo3FScientistEndBattleText"] = "Mi hai\nsconfitto!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Lavoro per la SILPH\nS.p.A. Cosa\11dovrei fare?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Tu\ne i tuoi POKéMON\11ci avete salvati!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Ah ah ah! Il mio\nCAPO cercava\11proprio questo posto!",
  ["_SilphCo4FRocket1BattleText"] = "Il TEAM ROCKET ha\npreso il controllo\11della SILPH S.p.A.!",
  ["_SilphCo4FRocket1EndBattleText"] = "Argh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "È meglio che vada\na dirlo al CAPO\11al 10º piano!",
  ["_SilphCo4FRocket2BattleText"] = "Intruso\nindividuato!",
  ["_SilphCo4FRocket2EndBattleText"] = "Tu chi\nsei?",
  ["_SilphCo4FScientistAfterBattleText"] = "Le porte sono\nchiuse elettronicamente!\11Si aprono con una\11TESSERA MAGNES.",
  ["_SilphCo4FScientistBattleText"] = "I miei POKéMON\nsono i miei fedeli\11soldati!",
  ["_SilphCo4FScientistEndBattleText"] = "\nHai indebolito\nil mio POKéMON!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Ssh! Non vedi\nche mi sto\11nascondendo?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Eh? Il TEAM\nROCKET se n'è andato?",
  ["_SilphCo5FPokemonReport1Text"] = "RAPPORTO sui POKéMON!\nPORYGON, il primo\11POKéMON virtuale,\12è stato creato nel\nLABORATORIO POKéMON.",
  ["_SilphCo5FPokemonReport2Text"] = "RAPPORTO sui POKéMON!\nConfermati più\11di 160 attacchi\11di POKéMON!",
  ["_SilphCo5FPokemonReport3Text"] = "RAPPORTO sui POKéMON!\nCi sono 4 POKéMON\12che si evolvono\nsolo se scambiati\11tramite cavo link!",
  ["_SilphCo5FRockerAfterBattleText"] = "Sei arrivato solo\nal 4º piano! Il mio\11CAPO è ancora\11molto lontano!",
  ["_SilphCo5FRockerBattleText"] = "Cosa? Qui non\ndovrebbero esserci\11bambini!",
  ["_SilphCo5FRockerEndBattleText"] = "\nOh no!\nMio Dio!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Non è molto furbo\nprovocare il\11TEAM ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Dicono che ci fosse\nun bambino qui\11intorno.",
  ["_SilphCo5FRocket1EndBattleText"] = "Buum!",
  ["_SilphCo5FRocket2AfterBattleText"] = "Questo mi ricorda\nche...\nKOFFING si\11evolve in WEEZING!",
  ["_SilphCo5FRocket2BattleText"] = "Porta un po' di\nrispetto al TEAM\11ROCKET!",
  ["_SilphCo5FRocket2EndBattleText"] = "\n(Tossisce)...",
  ["_SilphCo5FScientistAfterBattleText"] = "Stiamo lavorando\na una nuova POKé BALL\11capace di catturare\11qualsiasi cosa!",
  ["_SilphCo5FScientistBattleText"] = "In questo piano\nstudiamo la tecnologia\11delle POKé BALL!",
  ["_SilphCo5FScientistEndBattleText"] = "Uff!\nMaledizione!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "Il TEAM ROCKET\ncerca un intruso.\nStanno cercando\11te, vero?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "Il TEAM ROCKET\nse n'è andato!\11Grazie! Sei un eroe!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Non importa!\nI miei fratelli mi\11vengeranno!",
  ["_SilphCo6FRocket1BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "\nArrostito!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Se sostieni la\ngiustizia, tradisci\11il male!",
  ["_SilphCo6FRocket2BattleText"] = "Hai osato tradire\nil TEAM ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "Sei\nun traditore!",
 ["_SilphCo6FScientistAfterBattleText"] = "La FILIAL TIKSI?\nÈ in mezzo al nulla!",
  ["_SilphCo6FScientistBattleText"] = "Quel marcio del\nPRESIDENTE!\nNon doveva mandarmi\11alla FILIALE TIKSI!",
  ["_SilphCo6FScientistEndBattleText"] = "\nSono finito!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Mi faceva così\ntanta pena che\11ho deciso di sposarlo!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Guardalo! È un\nvile codardo!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "Il TEAM ROCKET\nvuole conquistare\11il mondo con i POKéMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Il TEAM ROCKET\nè fuggito per\11colpa tua!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Meglio tornare\nal lavoro!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "I ROCKET sono\narrivati e hanno\11preso il palazzo!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "La SILPH sembra\ninteressargli per\11i nostri prodotti\11POKéMON.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Vieni a lavorare\nper la SILPH quando\11sarai grande!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Oh, per favore!\nAiutami!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Ci siamo fidanzati!\nAh ah!",
  ["_SilphCo7FRivalDefeatedText"] = "Ah!\nQuindi sei pronto\11a lottare contro\11il CAPO ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Bene {PLAYER}!\nContinuo a migliorare!\12Posso scoprire i\npiù forti e come\11evolvono dal POKéDEX!\12Vado alla LEGA\nPOKéMON a battere\11i SUPERQUATTRO!\12Sarò il migliore!\n{PLAYER}, buona\11fortuna! Ciao!",
