  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Come\ndirlo...\nNon sei abbastanza\11bravo per giocare\11con i grandi!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Ah ah!\nSapevo che saresti\11venuto aspettando!\12Il TEAM ROCKET\nti avrà rallentato!\12Ti ho visto a\nZAFFERANOPOLI e\11ho voluto aspettare!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Non troverai il\nCAPO gironzolando\11a caso!",
  ["_SilphCo7FRocket1BattleText"] = "Uh-oh!\nSento odore di topo!",
  ["_SilphCo7FRocket1EndBattleText"] = "\nLuci spente!",
