  ["_SilphCo7FRocket3BattleText"] = "Un bambino intruso?\nDevi essere tu!",
  ["_SilphCo7FRocket3EndBattleText"] = "D'accordo!\nHo perso!",
  ["_SilphCo7FScientistAfterBattleText"] = "Nonostante l'età,\nsei un ottimo\11allenatore!",
