  ["_SilphCo7FScientistEndBattleText"] = "\nSono finito!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Ciao! Non\nsei un ROCKET!\11Sei venuto a\11salvarci? Grazie!\12Ti do questo POKéMON\nper averci salvato.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Il CAPO del TEAM\nROCKET è andato\11nella sala riunioni!\11Il PRESIDENTE sta bene?",
