  ["_SilphCo7FSilphWorkerM1SavedText"] = "Salvati!\nGrazie mille!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "Il TEAM ROCKET\ncercava la MASTER\11BALL per catturare\11qualsiasi POKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Abbiamo cancellato\nil progetto MASTER BALL\11a causa del\11TEAM ROCKET.",
