  ["_VermilionCityBeautyText"] = "¡Nos preocupa la\ncontaminación!\12¡Dicen que GRIMER\nse multiplica en\11residuos tóxicos!",
  ["_VermilionCityGambler1DidYouSeeText"] = "¿Viste al S.S.\nANNE anclado en\11el puerto?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "¡El S.S.ANNE\nha zarpado!\12Volverá en\nun año.",
  ["_VermilionCityGambler2Text"] = "Voy a construir\nun edificio en\11este trozo de\11tierra.\12Mi POKéMON\nestá apisonando\11la tierra.",
  ["_VermilionCityGymSignText"] = "LÍDER del GIMNASIO\nPOKéMON de la\11CIUDAD CARMÍN:\11LT. SURGE\12¡El Rayo\nAmericano!",
  ["_VermilionCityHarborSignText"] = "PUERTO CARMÍN",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\12¡Un MACHOP está\napisonando la\11tierra!",
  ["_VermilionCityMachopText"] = "MACHOP: ¡Chop!\n¡Chop!",
  ["_VermilionCityNoticeSignText"] = "¡AVISO!\12La RUTA 12 podría\nestar bloqueada\11por un POKéMON\11dormido.\12Desvíate a través\ndel TÚNEL ROCA al\11PUEBLO LAVANDA.\12POLICÍA de CARMÍN",
  ["_VermilionCityPokemonFanClubSignText"] = "CLUB de FANS\nde POKéMON\11¡Bienvenidos\11todos!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "¡Bienvenido al\nS.S. ANNE!\12Disculpe, ¿tiene\nsu ticket?",
