  ["_VermilionCitySailor1ShipSetSailText"] = "El barco zarpó.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "¡Bienvenido al\nS.S. ANNE!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} no\ntiene el TICKET\11del BARCO.\12¡Lo siento!\12Necesita un\nticket para\11subir a bordo.",
  ["_VermilionCitySailor2Text"] = "El S.S.ANNE es un\nfamoso y lujoso\11crucero.\12Visitamos la\nCIUDAD CARMÍN\11una vez al año.",
  ["_VermilionCitySignText"] = "CIUDAD CARMÍN\nEl puerto de\11los ocasos\11exquisitos.",
  ["_VermilionGymGentlemanAfterBattleText"] = "¿No se abrirá\nla puerta?\12¡El LT. SURGE\nsiempre fue\11muy cuidadoso!",
  ["_VermilionGymGentlemanBattleText"] = "¡Cuando estaba en\nel EJÉRCITO, el\11LT. SURGE era\11muy estricto!",
  ["_VermilionGymGentlemanEndBattleText"] = "¡Alto!\n¡Eres muy bueno!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "¡Uau! ¡Vaya pelea\ntan eléctrica!",
  ["_VermilionGymGymGuideChampInMakingText"] = "¡Hola, posible\ncampeón!\12El LT. SURGE\ntiene un mote.\11¡La gente le\11llama el Rayo\11Americano!\12¡Es un experto\nen los POKéMON\11eléctricos!\12¡Los POKéMON\nvoladores y los\11acuáticos están\11en peligro! ¡Ten\11cuidado con la\11parálisis!\12¡El LT. SURGE es\nmuy cuidadoso!\12¡Descifra un\ncódigo y\11llegarás a él!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "¡Te daré un\npequeño consejo!\12¡La electricidad\nes muy potente!\12¡Pero no afecta\na los POKéMON\11del tipo-tierra!",
  ["_VermilionGymLTSurgePreBattleText"] = "¡Oye, chaval!\n¿Pero qué haces?\12¡No resistirás\nmucho luchando!\11¡Seguro!\12¡Debes saber que\nlos POKéMON\11eléctricos me\11salvaron durante\11la guerra!\12¡Paralizaron a\nmis enemigos!\12¡Y eso mismo voy\na hacer yo\11contigo!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "¡Guau!\12¡Tú sí que eres\nfuerte, chico!\12¡Bien, toma la\nMEDALLA-TRUENO!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "¡Mejor que le\nhagas sitio!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "¡La MEDALLA-\nTRUENO aumenta\11la VELOCIDAD de\11tus POKéMON!\12¡Y permite volar\na tus POKéMON\11cuando quieran!\12¡Tú eres muy\nespecial, chaval!\11¡Toma esto!",
  ["_VermilionGymSailorAfterBattleText"] = "LT. SURGE\ncolocó dobles\11cerraduras. ¡Te\11daré una pista!\12¡Tras abrir la\n1a. cerradura, la\112a. está al lado!",
  ["_VermilionGymSailorBattleText"] = "¡Este lugar no\nes para niños!",
  ["_VermilionGymSailorEndBattleText"] = "¡Uuuaa!\n¡Me sorprendiste!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "¡Vale, hablaré!\12¡LT. SURGE dijo\nque ocultaría los\11botones de la\11puerta dentro\11de algo! ",
  ["_VermilionGymSuperNerdBattleText"] = "¡No es que yo sea\nmuy fuerte, pero\11soy muy bueno con\11la electricidad!",
  ["_VermilionGymSuperNerdEndBattleText"] = "\n¡Machacado!",
  ["_VermilionGymTrashFailText"] = "¡No! Aquí sólo\nhay basura. ¡Las\11cerraduras\11eléctricas fueron\11reajustadas!",
  ["_VermilionGymTrashSuccessText1"] = "¡Oye! ¡Hay un\nbotón debajo\11de la basura!\11¡Púlsalo!\12Abierto primer\ncierre eléctrico.",
  ["_VermilionGymTrashSuccessText2"] = "¡Oye! ¡Hay otro\nbotón debajo de\11la basura!\11¡Púlsalo!",
  ["_VermilionGymTrashSuccessText3"] = "Abierto segundo\ncierre eléctrico.\12¡Abierta la\npuerta mecánica!",
  ["_VermilionGymTrashText"] = "¡No, aquí sólo\nhay basura!",
  ["_VermilionMartCooltrainerFText"] = "Creo que los\nPOKéMON pueden\11ser buenos o\11malos. Todo\11depende del\11entrenador.",
  ["_VermilionMartCooltrainerMText"] = "Hay gente mala\nque utiliza a\11los POKéMON\11para cometer sus\11actos criminales.\12El TEAM ROCKET\ntrafica con raros\11POKéMON.\12Y prescinde de\naquellos POKéMON\11que no sean muy\11populares o\11útiles.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "¡Yo soy el GURÚ\nPESCADOR!\12¡Me encanta\npescar!\12¿Y a ti, te gusta\npescar?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\12¡Pescar es una\nforma de vivir!\12¡Del mar a los\nríos, zarpa y\11pesca el más\11grande, chaval!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "¡Hola\n{PLAYER}!\12¿Qué, pican\nlos peces?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "¡Oh no!\12¡No tienes sitio\npara mi regalo!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "¡Fenomenal! ¡Me\ngusta tu estilo!\12¡Toma esto y\npesca, jovencito!\12¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "¡Oh!...bueno...\n¡Qué pena!...",
  ["_VermilionPidgeyHouseLetterText"] = "Querido PIPPI,\nespero verte\11pronto.\12Dicen que en la\nCIUDAD AZAFRÁN\11tienen problemas\11con TEAM ROCKET.\12La CIUDAD CARMÍN\nparece segura.",
  ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: ¡Pid pid!",
  ["_VermilionPidgeyHouseYoungsterText"] = "¡Mi PIDGEY volará\nal norte, a la\11CIUDAD AZAFRÁN\11para llevar una\11carta!",
  ["_VermilionPokecenterFishingGuruText"] = "Aunque sean del\nmismo nivel, los\11POKéMON pueden\11tener diferentes\11habilidades.\12Un POKéMON\nentrenado es más\11fuerte que uno\11salvaje.",
  ["_VermilionPokecenterGuyText"] = "Es cierto que un\nPOKéMON de un\11nivel superior\11es más fuerte.\12Pero todos los\nPOKéMON son\11vulnerables ante\11ciertos tipos.\12Es decir, que no\nhay POKéMON\11invulnerables.",
  ["_VermilionPokecenterSailorText"] = "¡Mi POKéMON\nfue envenenado\11mientras\11caminábamos!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "¡A mí no me\ngusta perder!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "¡Me pregunto si\neres lo bastante\11bueno para mí!",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "¡He\nperdido!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "¡Lo admito, eres\nmejor que yo!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "¡Ya veo que eres\nbueno! ¡Veamos\11exactamente cómo\11de bueno!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "\nTuve una\11oportunidad...",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "¡Ahora puedes\nrecorrer la\11CALLE VICTORIA!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "¡Adelante! ¡Te\ndaré una paliza!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "¡Me has\nmachacado!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "¡Prueba a mover\nlas rocas si\11estás bloqueado!",
  ["_VictoryRoad2FHikerBattleText"] = "¡La CALLE\nVICTORIA es la\11prueba final de\11todo entrenador!",
  ["_VictoryRoad2FHikerEndBattleText"] = "¡Aiiii!",
  ["_VictoryRoad2FMoltresBattleText"] = "¡Mol Tres!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "¡{RIVAL} también\nvino por aquí!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "¡Ah! ¿Quieres\ndesafiar al\11ALTO MANDO?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "\n¡Me has ganado!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "¡Puedo vencerte\nen cuanto a\11conocimientos\11sobre los\11POKéMON!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "¡Si puedes pasar\npor aquí, podrás\11enfrentarte al\11ALTO MANDO!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "¡No!\n¡Increíble!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "¡Muchos de los\nentrenadores\11se rinden aquí!",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "¿Es muy dura la\nCALLE VICTORIA?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "\n¡Bien hecho!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "¡Me demostraste\nlo buena que era!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "¡Te demostraré lo\nbueno que eres!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "\n¡Argh!\11¡Me enfurezco!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "¡Librar duros\ncombates te hará\11más fuerte!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "¡Los entrenadores\nsólo viven para\11buscar enemigos\11más fuertes!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "\n¡Oooooh!\11¡Eres tan fuerte!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "¿Derrotaste a\nGIOVANNI del\11TEAM ROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "¡Los rumores\nhablan de un\11niño prodigio!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "\n¡Los rumores\11eran ciertos!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "¡Todos estos\nentrenadores\11van a participar\11en la LIGA\11POKéMON!\11¡Ten cuidado!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "¡Aquí sólo\npueden pasar\11los elegidos!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "¡No\nme lo puedo\11creer!",
  ["_VictreebelDexEntry"] = "Vive en grandes\ncolonias en el\ninterior de las\12junglas, aunque\nnadie ha podido\nverificarlo",
  ["_VileplumeDexEntry"] = "A mayor pétalo,\nmás tóxico es su\npolen. Su\12cabeza es pesada\ny le cuesta\nmantenerla",
  ["_ViridianBlackboardBurnText"] = "Toda quemadura\nreduce potencia\11y velocidad. Y\11causa daños\11progresivos.\12Las quemaduras\npermanecerán tras\11el combate.\12¡ANTIQUEMADURAS\ncurará las\11quemaduras!",
  ["_ViridianBlackboardFrozenText"] = "¡Todo POKéMON\ncongelado no\11podrá moverse!\12Y permanecerá\ncongelado tras\11el combate.\12¡Usa el ANTIHIELO\npara descongelar\11a los POKéMON!",
  ["_ViridianBlackboardPoisonText"] = "Todo POKéMON\nenvenenado\11seguirá perdiendo\11energía.\12El veneno sigue\nafectándoles tras\11el combate.\12¡Usa un ANTÍDOTO\npara curarlos!",
  ["_ViridianBlackboardPrlzText"] = "¡Paralizar podría\nanular ciertos\11movimientos!\12La parálisis\npermanecerá tras\11el combate.\12Usa ANTIPARALIZAR\npara curarlos.",
  ["_ViridianBlackboardSleepText"] = "¡Un POKéMON no\npuede atacar si\11está dormido!\12¡Los POKéMON\nseguirán dormidos\11incluso después\11de pelear!\12¡Usa DESPERTAR y\nse despertarán!",
  ["_ViridianCityFisherReceivedTM42Text"] = "¡{PLAYER} recibió\nla MT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "La MT42 contiene\nel COME-SUEÑOS...\11(Ronquido)...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Tienes demasiadas\ncosas.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Este GIMNASIO\nPOKéMON está\11siempre cerrado.\12Me pregunto quién\nserá su LÍDER.",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "¡Regresó el\nLÍDER del\11GIMNASIO VERDE!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "¡Oh abuelo! ¡No\nseas tan malo!\11Todavía no se ha\11tomado un café.",
  ["_ViridianCityGirlWhenIGoShopText"] = "¡Cuando voy de\ncompras a la\11CIUDAD PLATEADA,\11tomo el sinuoso\11camino del BOSQUE\11VERDE!",
  ["_ViridianCityGymLockedText"] = "Las puertas del\nGIMNASIO están\11cerradas...",
  ["_ViridianCityGymSignText"] = "GIMNASIO POKéMON\nde CIUDAD VERDE",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "¡Ya me tomé\nun café y me\11siento genial!\12¡Claro que\npuedes pasar!\12¿Tienes prisa?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Ya veo que tienes\nuna POKéDEX.\12Cuando atrapes un\nPOKéMON, la\11POKéDEX será\11automáticamente\11actualizada.\12¿Qué? ¿No sabes\ncómo atrapar un\11POKéMON?\12Pues yo te\nenseñaré.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "¡No puedes pasar\npor aquí!\12¡Es propiedad\nprivada!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "El tiempo es oro.\nSigue tu camino.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Primero tendrás\nque debilitar al\11POKéMON objetivo.",
  ["_ViridianCityPokecenterGuyText"] = "¡Los CENTROS\nPOKéMON curan\11a tus POKéMON\11heridos o\11derrotados!",
  ["_ViridianCitySignText"] = "CIUDAD VERDE\nEl Paraíso del\11eterno verdor.",
  ["_ViridianCityTrainerTips1Text"] = "PISTAS ENTRENADOR\12¡Atrapa a los\nPOKéMON y amplía\11tu colección!\12¡Cuantos más\ntengas más fácil\11te será luchar!",
  ["_ViridianCityTrainerTips2Text"] = "PISTAS ENTRENADOR\12Los ataques de\nlos POKéMON\11dependen de sus\11PUNTOS DE\11PODER o PP.\12¡Para rellenar\ntus PP, deja que\11tus cansados\11POKéMON\11descansen en un\11CENTRO POKéMON!",
  ["_ViridianCityYoungster1Text"] = "¡Esas POKé BALL\nde tu cintura!\11¡Tienes POKéMON!\12¡Es genial poder\nllevar y usar los\11POKéMON en\11cualquier momento\11y lugar!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "¿Quieres saber\nalgo sobre los 2\11tipos de orugas\11POKéMON?",
  ["_ViridianForestLeavingSignText"] = "SALIENDO DEL\nBOSQUE VERDE. LA\11CIUDAD PLATEADA\11ESTÁ ENFRENTE.",
  ["_ViridianForestNorthGateGrampsText"] = "¿Has visto los\narbustos que hay\11junto al camino?\12Puedes cortarlos\ncon un movimiento\11especial de los\11POKéMON.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Muchos POKéMON\nsólo viven en\11bosques y cuevas.\12¡Tienes que mirar\npor todas partes\11para conseguirlos\11todos!",
  ["_ViridianForestSouthGateGirlText"] = "¿Piensas ir al\nBOSQUE VERDE?\11¡Ten cuidado!\11¡Es un auténtico\11laberinto!",
  ["_ViridianForestSouthGateLittleGirlText"] = "¡Puede que\nRATTATA sea\11pequeño, pero\11su mordisco es\11muy potente!\11¿Tienes alguno?",
  ["_ViridianForestTrainerTips1Text"] = "PISTAS ENTRENADOR\12Si quieres evitar\nlos combates,\11¡aléjate de las\11zonas de hierba!",
  ["_ViridianForestTrainerTips2Text"] = "PISTAS ENTRENADOR\12¡Para evaluar tu\nPOKéDEX, llama\11al PROF. OAK\11vía PC!",
  ["_ViridianForestTrainerTips3Text"] = "PISTAS ENTRENADOR\12¡No robes los\nPOKéMON\11de otros\11entrenadores!\11¡Captura sólo a\11los POKéMON\11salvajes!",
  ["_ViridianForestTrainerTips4Text"] = "PISTAS ENTRENADOR\12¡Debilita a los\nPOKéMON antes\11de intentar\11capturarlos!\12¡Si están\nfuertes,\11podrían escapar!",
  ["_ViridianForestUseAntidoteSignText"] = "¡Usa ANTÍDOTO\ncontra el veneno!\11¡Lo conseguirás\11en las TIENDAS\11POKéMON!",
  ["_ViridianForestYoungster1Text"] = "¡Vine aquí con\nunos amigos!\12¡Van en busca\nde peleas de\11POKéMON!",
  ["_ViridianForestYoungster2AfterBattleText"] = "¡Ssh! ¡Vas a\nespantar a\11los bichos!...",
  ["_ViridianForestYoungster2BattleText"] = "¡Eh! ¡Tienes\nPOKéMON! ¡Sí!\11¡Al ataque!",
  ["_ViridianForestYoungster2EndBattleText"] = "¡No!\n¡CATERPIE no\11pudo cortarlo!",
  ["_ViridianForestYoungster3AfterBattleText"] = "¡Maldición! \n¡Voy a atrapar\11unos más fuertes!",
  ["_ViridianForestYoungster3BattleText"] = "¡Eh! ¡Debes\nser disciplinado\11para ser un\11entrenador de\11POKéMON!",
  ["_ViridianForestYoungster3EndBattleText"] = "¡Ups!\n¡No me quedan\11más POKéMON!",
  ["_ViridianForestYoungster4AfterBattleText"] = "¡A veces puedes\nencontrar cosas\11en el suelo!\12¡Estoy buscando\nlos objetos que\11dejé caer!",
  ["_ViridianForestYoungster4BattleText"] = "¡Eh, espera!\n¿Por qué tienes\11tanta prisa?",
  ["_ViridianForestYoungster4EndBattleText"] = "\n¡Me rindo! ¡Eres\11demasiado bueno!",
  ["_ViridianForestYoungster5Text"] = "¡Me quedé sin\nPOKé BALL con\11las que atrapar a\11los POKéMON!\12¡Deberías llevar\nalgunas extra!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "¡Necesitas\npotencia para\11luchar contra el\11LÍDER-GIMNASIO!",
  ["_ViridianGymCooltrainerM1BattleText"] = "¡Oye! ¡Ya no\ndebe de quedarte\11nada de vapor!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "¡Me\nquedé sin gas!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "¡El LÍDER me\nva a reñir!",
  ["_ViridianGymCooltrainerM2BattleText"] = "¡Los más hábiles\nganan con estilo!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "\n¡Perdí el\11control!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "¡Sólo accederás a\nla LIGA POKéMON\11ganando a nuestro\11LíDER-GIMNASIO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "¡El GIM. VERDE\nestuvo cerrado\11mucho tiempo,\11pero nuestro\11LÍDER ha vuelto!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "\n¿Acaso fui\11derrotado?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "¡Con la MEDALLA-\nTIERRA, todos los\11POKéMON te\11obedecerán!\12¡Es una prueba de\ntu maestría como\11entrenador de\11POKéMON!\12¡Con ella podrás\nacceder a la\11LIGA POKéMON!\12¡Es mi regalo por\ndesafiar a la\11LIGA POKéMON!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "¡Como perdí, ya\nno soy digno de\11dirigir a mis\11secuaces! ¡Se\11acabó el TEAM\11ROCKET!\12¡Dedicaré mi vida\nal estudio de\11los POKéMON!\12¡Espero que nos\nvolvamos a ver!\11¡Adiós!",
  ["_ViridianGymGiovanniPreBattleText"] = "¡Ajajaja! ¡Ésta\nes mi guarida!\12¡Quería reformar\nal TEAM ROCKET\11desde aquí!\12¡Pero me volviste\na encontrar!\11¡Estoy furioso!\11¡Esta vez no me\11pienso contener!\12¡Volverás a\nenfrentarte al\11gran GIOVANNI, el\11súper entrenador!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "¡Ja!\n¡Fue un duro\11combate! ¡Y has\11ganado! ¡Como\11premio, toma esta\11MEDALLA-TIERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "¡{PLAYER} ganó\nla MT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\12¡MT27 es FISURA!\n¡Ésta derrotará\11a los POKéMON de\11un solo ataque!\12La inventé cuando\ndirigía este\11GIMNASIO, hace ya\11mucho tiempo...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_ViridianGymGuidePostBattleText"] = "¿Qué dices? ¿Que\nGIOVANNI era el\11LÍDER del\11GIMNASIO?",
  ["_ViridianGymGuidePreBattleText"] = "¡Hola,\nposible campeón!\12¡Ni yo conozco\nla identidad del\11LÍDER VERDE!\12¡Éste será el más\nduro de todos los\11LÍDERES-GIMNASIO!\12¡Dicen que estos\nentrenadores usan\11los POKéMON\11del tipo TIERRA!",
  ["_ViridianGymHiker1AfterBattleText"] = "¡Sigo sin\nmerecérmelo!",
