  ["_ViridianGymHiker1EndBattleText"] = "¡Rargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Si mis POKéMON\nfueran tan buenos\11karatekas...",
  ["_ViridianGymHiker2BattleText"] = "¡El karate es lo\nmáximo en artes\11marciales!",
  ["_ViridianGymHiker2EndBattleText"] = "¡Aachú!",
  ["_ViridianGymHiker3AfterBattleText"] = "¿La LIGA POKéMON?\n¿Tú? ¿Pero quién\11te crees?",
